window.harnessChunks["rows-aba83a15fc6373a7.js"]=["<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-17T23:12:14+03:00\"><th scope=\"row\"><a href=\"https://github.com/eigent-ai/eigent\" target=\"_blank\" rel=\"noopener\">Eigent</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/eigent-ai/eigent/tree/6c49956b2aa878c08bee5edcf8a1eb63122c2cd9\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6c49956b2aa878c08bee5edcf8a1eb63122c2cd9\">6c49956 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: A. Workforce agents autonomously execute assigned tool/model work.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: A. The task agent produces an explicit dependency graph and runnable work is published only after dependencies are satisfied; the model-driven workforce path selects assignees and reacts to task state. This closes dependency/ordering interference across autonomous S1s rather than merely routing messages.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: A. The model-driven coordinator has a workforce-wide view and authority over assignment, retries/replanning and current task progression. These are current whole-team regulation decisions owned by an autonomous first-party agent path.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. No materially independent complementary audit channel with distinct evidence access and corrective closure was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. Planning and replanning address current task execution; no separate prospective environment-facing organizational adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Human permissions/configuration constrain execution but do not establish identity/ultimate-policy closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/aa0f4fc244d04c276678f55ed941376422a344af/assessments/eigent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit aa0f4fc244d04c276678f55ed941376422a344af\">aa0f4fc &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"1\" data-assessment-at=\"2026-10-12T14:26:17+03:00\"><th scope=\"row\"><a href=\"https://github.com/awslabs/cli-agent-orchestrator\" target=\"_blank\" rel=\"noopener\">CLI Agent Orchestrator</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-12\">2026-10-12</time></td><td class=\"review-ref\"><a href=\"https://github.com/awslabs/cli-agent-orchestrator/tree/ffa9fc742c7d47ce038d3d951ccc5527ba0c0218\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ffa9fc742c7d47ce038d3d951ccc5527ba0c0218\">ffa9fc7 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Multiple model-directed worker sessions implement assigned coding/review tasks and return artifacts/findings to the supervisor through the supported CAO runtime. - Disturbance / variety regulated: User requests, changing code, individual task failures and defects, separate worker provider responses. - Decisive decision or feedback right: CAO-started worker agents decide how to perform the delegated task within their advertised developer/reviewer role; the supervisor allocates tasks separately. - Decision owner: Shipped first-party configured agent profiles running model-driven sessions through supported external CLI providers; external provider reasoning details are not credited as first-party code. - Supporting / enforcement mechanisms: Profile roles, terminal/provid­er adapter, model process, CAO MCP messages and terminal session manager. - Closure path: Supervisor task/message → first-party-created worker CLI context → worker produces code/review findings → CAO handoff output or inbox callback → supervisor sees completion and selects follow-up. - Boundary reachability: The documented install/launch path exposes built-in codesupervisor; its MCP server can launch developer/reviewer sessions from installed first-party profiles (README.md; src/cliagentorchestrator/agentstore/codesupervisor.md; src/cliagentorchestrator/utils/orchestration.py). - Why this is / is not agent-owned: Work and review choices are generated by actual delegated agent roles, not a deterministic tmux replay; no claim is made about external provider-native internal planning. - Evidence: README.md; src/cliagentorchestrator/agentstore/developer.md; src/cliagentorchestrator/agentstore/reviewer.md; src/cliagentorchestrator/mcpserver/server.py; src/cliagentorchestrator/mcpserver/server.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Prevent damaging shared-source interference among separately acting coding workers when the supported opt-in worktree isolation mode is used. - Distinct S1 units: Independently launched developer/worker terminal sessions via the first-party assign/handoff MCP tools (src/cliagentorchestrator/mcpserver/server.py; src/cliagentorchestrator/mcpserver/server.py). - Inter-S1 disturbance: Concurrent spawned workers share a Git checkout by default and can race/overwrite one another&#39;s edits or create merge conflicts; first-party worktree service explicitly identifies these exact hazards (src/cliagentorchestrator/services/worktreeservice.py). - Attenuating coordination relation: Supervisor&#39;s opt-in worktree parameter causes CAO to create distinct branch/checkouts for individual child sessions, separating conflicting write contexts; worker results return to the supervisor for explicit integration. - Feedback into subsequent S1 behaviour: Worktree-provisioned workers execute in separated checkouts, return task outcome through handoff or inbox callback; supervisor then selects further assignments/repair or integration rather than allowing concurrent edits to the original shared checkout (src/cliagentorchestrator/utils/orchestration.py; src/cliagentorchestrator/mcpserver/server.py). - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: Evidence ties per-worker isolation directly to an explicitly documented concrete inter-worker file race/overwrite hazard, not to ordinary message delivery or terminal creation alone. - Disturbance / variety regulated: Overlapping mutations and checkout interference between active coding units. - Decisive decision or feedback right: The choice to request isolated worktree mode belongs to supervisor/constructor configuration; CAO creates a fresh branch/worktree and enforces the isolated execution context. - Decision owner: First-party optional isolation constructor with developer/supervisor-provided enablement; no autonomous S2-level admission or merge-convergence policy is shown. - Supporting / enforcement mechanisms: Per-worker server-generated terminal ID, Git worktree creation, per-terminal checkout path, cleanup, MCP assign/handoff callback. - Closure path: Explicit collision risk → assign/handoff with useworktree=True → distinct Git branches and isolated next S1 edits → result delivered to supervisor → subsequent unit work/integration decisions. - Boundary reachability: useworktree is a shipped argument on both first-party MCP tools and forwarded to the local terminal service; createworktree makes an actual branch/checkout (src/cliagentorchestrator/mcpserver/server.py; src/cliagentorchestrator/utils/orchestration.py; src/cliagentorchestrator/services/worktreeservice.py). - Why this is / is not agent-owned: Contention-specific relation is built by CAO; the optional activation owner is the supervisor but no independent agent S2 conflict-resolution policy is presumed. - Evidence: src/cliagentorchestrator/services/worktreeservice.py; src/cliagentorchestrator/services/worktreeservice.py; src/cliagentorchestrator/utils/orchestration.py; src/cliagentorchestrator/mcpserver/server.py. - Basis: explicit - Confidence: medium - Caveats: Positive restricted to explicitly enabled per-worker worktree mode; default shared directory does not receive this S2 closure. No automatic conflict-free merge or code acceptance is claimed.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: First-party model-driven codesupervisor governs commitments and rework across its active developer and reviewer worker units. - Disturbance / variety regulated: Unfinished assignments, failed/defective code, availability and outputs of launched agents, shared artifact paths. - Decisive decision or feedback right: Supervisor chooses which worker gets each task, when findings trigger rework and when review is satisfactory. - Decision owner: Bundled codesupervisor model role, not the tmux scheduler, status endpoint or underlying provider&#39;s hidden native agent hierarchy. - Supporting / enforcement mechanisms: CAO assign/handoff, result callbacks, inbox delivery/status, supervisor file/task directory rules. - Whole-system current view: Within the expressly bounded supervisor team, supervisor tracks assigned tasks, known code artifacts, callbacks and reviewer findings, not all sessions/fleets of external agents. - Current-control decision scope: Developer/reviewer assignment, repair/retry commitments and task convergence at the supervisor-team recursion. - Closure path: Subordinate outcomes and reviewer feedback → supervisor checks team current work and chooses assignment/retry/approval → new worker work and returned completion. - Boundary reachability: cao install codesupervisor and cao launch --agents codesupervisor are documented; its first-party role/instructions require task assignment, progress tracking, rework on failed review, and delegate through wired MCP tools (README.md; src/cliagentorchestrator/agentstore/codesupervisor.md; src/cliagentorchestrator/mcpserver/server.py). - Why this is / is not agent-owned: Supervisor decides commitments based on returned worker/reviewer observations; tool transport/terminal service only enforces dispatch and delivery. - Evidence: src/cliagentorchestrator/agentstore/codesupervisor.md; src/cliagentorchestrator/mcpserver/server.py; src/cliagentorchestrator/utils/orchestration.py. - Basis: explicit -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: A distinct code-review worker audits produced source/code artifacts and sends independent problem findings back into the supervisor&#39;s repair/acceptance loop. - Disturbance / variety regulated: Code quality, correctness, missing test coverage, security vulnerabilities in developer-produced work. - Decisive decision or feedback right: Dedicated reviewer model makes its own source-inspection judgment; supervisor decides whether findings require developer repair. - Decision owner: Separate built-in reviewer model session for audit judgment; supervisor owns follow-up commitments. - Supporting / enforcement mechanisms: First-party reviewer role/tool-access limits, shared artifact paths, CAO handoff/assign and return message mechanism. - Claim being audited: Developer completion/quality claims about newly produced project files. - Ordinary reporting path: Developer sends work artifacts/status to the CAO supervisor. - Complementary access path: A separately instantiated read-oriented reviewer receives source paths and inspects code independently of the developer&#39;s self-report. - Independence boundary: Separate worker terminal/profile, read-oriented reviewer tools and independently model-produced findings; it is neither the developer&#39;s own loop nor a deterministic assertion of completion. - Who acts on findings: Supervisor relays defects to developer, repeats review and decides when satisfied. - Closure path: Developer artifact → separate reviewer source examination → findings to supervisor → subsequent developer correction/re-review before finishing. - Boundary reachability: Built-in supervisor explicitly requires a code-review worker after development and repair loops; the shipped reviewer profile has a review-only role and sends findings back over the first-party MCP channel (src/cliagentorchestrator/agentstore/codesupervisor.md; src/cliagentorchestrator/agentstore/reviewer.md; docs/tool-restrictions.md). - Why this is / is not agent-owned: Distinct model reviewer produces content-specific defect judgments; model independence is role/process-level, not proof of different provider weights or guaranteed statistical independence. - Evidence: src/cliagentorchestrator/agentstore/codesupervisor.md; src/cliagentorchestrator/agentstore/reviewer.md; src/cliagentorchestrator/mcpserver/server.py; src/cliagentorchestrator/mcpserver/server.py. - Basis: explicit - Confidence: medium - Caveats: Positive only in the bundled developer+reviewer supervisor mode, not every launch. Reviewer is independently running but no claim is made of organizational independence outside this task-level CAO team.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: Optional learning/outcome/retrospector/instruction-promotion path might adapt future agents, but its external-prospective S4 function and decisive owner remain unresolved. - Disturbance / variety regulated: Recurring historical workflow failures and future task differences. - Decisive decision or feedback right: Retrospector stores lessons; separate operator must explicitly apply promoted lessons into agent profiles, but it is unproven whether this constitutes full outside-and-then intelligence rather than retrospective process optimization. - Decision owner: Mixed autonomous retrospector and operator for promotion; no complete S4 autonomous or first-party parent mode established. - Supporting / enforcement mechanisms: Outcome records, memoryrecall, retrospector profile, opt-in learning flags, cao memory promote --apply. - External distinction: Work outcomes can carry evidence of changing task environments, but the explicit external opportunity/threat prospective appraisal is not established. - Future / prospective distinction: Promoted lessons affect future new sessions, unlike an ordinary retry. - Adaptation option generated: Retrospector may distill up to three reusable lessons; human-triggered promotion writes them to future profiles. - Path back into current capability / S3: Profile learned patterns apply on later sessions; first-party prospective external intelligence judgment/authority boundary still under review. - Closure path: Reported outcome → retrospector lesson → user promotion → future profile instructions, without an established independent outside-and-then appraisal. - Why this is / is not agent-owned: Automatic memory capture and config editing do not by themselves establish the organizational S4 function. - Evidence: docs/self-learning.md; docs/self-learning.md; docs/self-learning.md; src/cliagentorchestrator/services/promotionservice.py. - Basis: unknown -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S5 / identity: - State: ? - Function: First-party tool roles and operator approval policy restrict action, but ultimate project identity/organizational policy authority return path remains unresolved. - Disturbance / variety regulated: Tool permissions, agent identities and allowed delegation, workflow safety/custody and operator oversight. - Decisive decision or feedback right: User/deployer selects launch permissions and approvals; roles bound available MCP/CLI actions. - Decision owner: Operator for safety and profile policy; model supervisor chooses within constraints. No S5-specific parent closure established. - Supporting / enforcement mechanisms: Role-based allowedTools, profile schema and permission checks, workflow plan approval gate with opt-in setting and persistent approved plan ID. - Identity / ultimate-policy issue: Accepted tool/role policy of the CAO session and approved workflow intent. - Ultimate authority in each claimed mode: Not credited; operator can approve specific actions, but project-wide identity/policy decision loop has not been established. - Return-to-operation path: Profile/tool restrictions affect what worker may call; workflow approval gates permit/deny runs. These are enforcement/approval paths, not proven ultimate-policy closure. - Closure path: Agent attempts tools → permission/approval checks → allowed/blocked execution; unresolved higher-level policy decision ownership. - Why this is / is not agent-owned: Read-only reviewer role and guarded workflow approval do not turn static constraints or generic human approval into S5. - Evidence: docs/tool-restrictions.md; src/cliagentorchestrator/services/approvalgate.py; src/cliagentorchestrator/agentstore/codesupervisor.md. - Basis: unknown -\">?</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/1dc2d2e352399be6e8e0ae673bd65d038049a708/assessments/cli-agent-orchestrator.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 1dc2d2e352399be6e8e0ae673bd65d038049a708\">1dc2d2e &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-17T20:13:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/langchain-ai/deepagents\" target=\"_blank\" rel=\"noopener\">Deep Agents</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/langchain-ai/deepagents/tree/f86b4e9abef7620b63a7258bc9fab0ccd83de8a4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f86b4e9abef7620b63a7258bc9fab0ccd83de8a4\">f86b4e9 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: the primary and delegated agents autonomously perform model/tool work.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: concurrent async tasks, isolation and lifecycle APIs establish multiple S1 units but no specific first-party inter-S1 interference/oscillation plus attenuation relation. Start/update/cancel/list are hierarchical current-control rights, not mutual-adjustment evidence by themselves.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the main agent has a live view of its tracked background commitments and model-facing authority to start, inspect, redirect/interupt, cancel and list those commitments. The decisive intervention is chosen by the autonomous main agent; SDK/LangGraph machinery transports and enforces it. This closes a current whole-subagent-set regulation loop without a developer having to supply another control actor.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: a separate rubric grader challenges a candidate completion and can independently gather read-only evidence through the first-party dcode wiring. needsrevision findings are returned into the primary loop and cause further work. This is materially complementary access plus autonomous audit judgment and feedback closure, rather than ordinary inline QA.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: rubric iteration, memory, skills and task updates concern present execution/quality. No separate prospective environment-facing loop that changes future organizational capability/strategy was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: HITL/interrupton, rubrics and runtime options can gate operational actions or define acceptance criteria, but they do not establish identity/ultimate-policy closure. Generic human interruption is therefore not S5=P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c/assessments/deepagents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c\">3c76cda &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-17T20:13:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/QwenLM/qwen-code\" target=\"_blank\" rel=\"noopener\">Qwen Code</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/QwenLM/qwen-code/tree/3ac6fe65e81c84897c02d22abd3dc91d1e567d5f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3ac6fe65e81c84897c02d22abd3dc91d1e567d5f\">3ac6fe6 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: coding agents autonomously perform tool-using work inside their assigned scope.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: multiple S1 teammates share task ownership and messages. Atomic claiming prevents duplicate task ownership, priority delivery changes subsequent teammate behavior, and bounded pending-message queues attenuate a concrete flood/interference mode. Agents choose task/message actions while TeamManager provides deterministic enforcement and feedback.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the team leader is an autonomous current-control actor over the team. It can create/direct teammates and invoke a leader-only shutdown that removes a teammate from participation and releases its task commitment; TeamManager supplies the whole-team state/lifecycle substrate and closes the intervention. Separately, Qwen Code&#39;s interactive approval mode can require the parent user to allow/deny these ask-classified team-control actions before execution, establishing a distinct parent-governed S3 mode.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no distinct complementary audit actor/path with materially different access to operational reality and findings returned into current control was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: no separate outside-and-future adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: approval modes and team-action permissions govern operational interventions. They do not establish a first-party identity/ultimate-policy question and legitimate ultimate-authority loop, so the previous generic S5=P interpretation is removed.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c/assessments/qwen-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c\">3c76cda &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/microsoft/agent-framework\" target=\"_blank\" rel=\"noopener\">Microsoft Agent Framework</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-16\">2026-09-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/microsoft/agent-framework/tree/1cd06c5a2058a172eebadf5d9d7c3fa45c519520\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1cd06c5a2058a172eebadf5d9d7c3fa45c519520\">1cd06c5 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: specialist agents autonomously perform bounded tool/model work and return operational outcomes.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: the Magentic manager actively detects loop/stall/no-progress conditions and changes team execution to restore convergence. This is agent-owned regulation of instability among operational units, not static graph topology.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the default Magentic manager owns a whole-team current-state ledger of facts/plan/progress, chooses who acts next, and has reset/replan authority over current commitments, establishing an autonomous S3 mode. The first-party plan-review option establishes a second parent-governed mode over the same S3 function: before a plan executes, a human sees the current progress ledger and proposed whole-team plan and may approve it or require revision; revision is returned to the manager, which replans before work continues. This is materially different from participant tool-call approval because it controls the team&#39;s current plan itself.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the same manager that regulates current work observes progress; no organizationally distinct complementary audit channel with independent access/authority was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: replanning responds to current execution failure. The reviewed implementation does not establish a separate prospective external-environment intelligence function that adapts future system capability/strategy.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: goals, participants, instructions and orchestration policy remain application-defined. Human signoff on a current Magentic plan is S3 current-control authority, not by itself ultimate organizational identity or policy closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/microsoft-agent-framework.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/matiasrodlo/veritas\" target=\"_blank\" rel=\"noopener\">Veritas</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/matiasrodlo/veritas/tree/f366432381834dee8ecb17bcbc2bad3e6232ff0b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f366432381834dee8ecb17bcbc2bad3e6232ff0b\">f366432 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: generate, debug, execute, compare, and refine experiment implementations to gather scientific evidence for the loaded research idea. - Disturbance / variety regulated: code/runtime failures, inadequate implementations, hyperparameter uncertainty, poor metrics, scaling choices, and uncertainty about which experimental change best tests the hypothesis. - Decisive decision or feedback right: choose candidate implementation changes and subsequent experiment actions in response to execution errors, journal history, metrics, and stage goals. - Decision owner: the model-driven tree-search research agent (ParallelAgent/candidate-generation path). - Supporting / enforcement mechanisms: isolated interpreter, execution timeout/resource controls, journals/tree nodes, named metrics and provenance, multi-seed evaluation, artifacts/plots, search configuration, and checkpoints. - Closure path: generated code is executed; errors/metrics/artifacts return into the search journal and prompts; subsequent nodes implement revisions or alternative experiments until stage criteria/limits are reached. - Boundary reachability: the tree-search agent and interpreter are the core path invoked by launchscientistbfts.py; no external agent harness supplies the experiment loop. - Why this is / is not agent-owned: deterministic execution and metric parsing constrain/measure candidates, but the model-driven agent chooses substantive implementation and experiment changes. - Evidence: README search description, tree-search runner, AgentManager agent creation. - Basis: explicit + structural. - Confidence: high. - Caveats: parallel candidates/tree branches are alternative attempts inside the operational research process; their plurality is not itself evidence of S2.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material S2-specific inter-S1 coordination loop is established at the declared recursion. - Disturbance / variety regulated: not established. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: worker isolation, process/resource limits, stage sequencing, shared journals, and candidate ranking prevent contamination or structure search but do not evidence a concrete interference/oscillation among distinct cooperating S1 units. - Closure path: not established. - Why this is / is not agent-owned: concurrent or branching experiment attempts are not automatically separate operational units requiring S2; they are candidate searches for one S1 research outcome. - Evidence: README execution/isolation description, experiment runner. - Basis: structural negative finding. - Confidence: high. - Caveats: a future multi-researcher mode would require a distinct S1 mapping and explicit interference/attenuation witness.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain current evidence about the whole active research search/stage and decide completion, next-substage focus, and progression of the experiment program. - Disturbance / variety regulated: stagnating search, unmet stage success criteria, unresolved implementation issues, insufficient improvement, under-scaled experiments, and uncertainty about the most useful next search focus. - Decisive decision or feedback right: decide whether the current stage/substage is complete and generate specific goals/focus for the next substage from current progress/issues/metrics. - Decision owner: AgentManager&#39;s model-driven feedback/evaluation path for discretionary completion/focus judgments, operating within deterministic minimum/max/adaptive-stopping constraints. - Supporting / enforcement mechanisms: full stage journal, best-node selection, success-criteria checks, improvement counters, deterministic stopping rules, stage history, checkpoints, and stage lifecycle code. - Closure path: current journal metrics/issues/recent changes are summarized into the feedback model; the resulting completion decision or generated substage goals alter stage lifecycle and the prompt/goals used by the next research agent. - Boundary reachability: AgentManager is the standard controller instantiated by the main tree-search runner, and its feedback model/path is configured as part of normal experiment execution. - Why this is / is not agent-owned: fixed timeouts/max-iterations and metric checks are enforcement. S3 credit comes from the additional model-driven current-control judgment that interprets current whole-stage evidence and creates the next research focus. - Whole-system current view: active stage journal, all attempts in that stage, good/buggy nodes, best metric/node, success-criteria progress, current issues/recent changes, stage history, and prior-stage best implementation when relevant. - Current-control decision scope: stage completion, continuation versus progression, and specific next-substage research goals/focus that determine subsequent resource/effort commitment within the run. - Evidence: AgentManager completion logic, next-substage goal generation, standard runner. - Basis: structural. - Confidence: high. - Caveats: not every AgentManager decision is autonomous: many limits/checks are deterministic. The positive state depends specifically on the model-driven completion and next-focus decisions wired into current operation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material operationally closed complementary-audit loop is established in the reviewed full-run path. - Disturbance / variety regulated: not established at S3 scope. - Decisive decision or feedback right: no independent audit right with corrective return is established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: metric provenance, multi-seed checks, plot/VLM checks, zero-data abort, and final automated paper review provide validation/review surfaces. - Closure path: the final review is written after the experiment search and paper generation, but the reviewed launcher does not feed its findings back into AgentManager, write-up, or experiments for corrective operation. - Why this is / is not agent-owned: performreview is a separate review action by name, but S3 requires complementary audit plus findings-to-control closure. Post-hoc persisted review without return is insufficient. - Evidence: launcher review path, README output including reviewtext.txt. - Basis: structural negative finding. - Confidence: high. - Caveats: internal VLM/metric validation is part of ordinary search acceptance/current control, while the separate final review lacks corrective return.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: in the supported idea-generation mode, sense external scientific literature, reflect on novelty/feasibility, and produce a future experiment program that the standard research run can execute. - Disturbance / variety regulated: risk that a proposed research direction duplicates existing work, misses relevant prior findings, or lacks a feasible/meaningful experimental plan. - Decisive decision or feedback right: choose/refine/finalize the research proposal after incorporating Semantic Scholar retrieval into repeated idea reflection. - Decision owner: the model-driven idea-generation agent. - Supporting / enforcement mechanisms: first-party Semantic Scholar tool, multi-round reflection history, prior-idea archive, structured FinalizeIdea schema, and instruction requiring at least one literature search before finalization. - Closure path: external literature results enter the reflection loop; the finalized idea includes related work, hypothesis, experiments, and risk factors; the resulting JSON is directly consumable by launchscientistbfts.py, where it determines subsequent staged experimental capability/work. - Boundary reachability: README documents performideationtempfree.py as the first-party way to create an ideas file from a short workshop brief; its output is the same schema consumed by the standard launcher. - Why this is / is not agent-owned: the literature tool retrieves external distinctions, but the model-driven ideation loop owns proposal selection/refinement; the experiment launcher then operationalizes the returned option. - External distinction: retrieved Semantic Scholar prior work and related-work information outside the current Veritas run. - Future / prospective distinction: novelty, feasibility, and which hypothesis/experimental direction should be pursued in later stages. - Adaptation option generated: finalized research idea containing hypothesis, related work, experiment plan, and risks/limitations. - Path back into current capability / S3: the idea JSON becomes the launcher&#39;s task description; AgentManager derives stage work from its experiment plan and executes the resulting research program. - Evidence: idea-generation tool and required literature search, README documented idea generation, launcher idea loading. - Basis: explicit + structural. - Confidence: high. - Caveats: the internal creativeresearch stage and reuse of previous experiment results are not the basis for S4. Credit depends on the distinct first-party external-literature → future idea → launched experiment closure.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material identity/ultimate-policy authority loop is established at the declared research-run recursion. - Disturbance / variety regulated: not established at S5 scope. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: user/workshop idea, structured idea schema, stage goals, configuration, model choices, resource limits, and review/write-up settings constrain operation. - Closure path: no identity/ultimate-policy issue is shown reaching a legitimate authority and returning as a binding decision to subsequent operation. - Why this is / is not agent-owned: idea generation chooses the scientific direction to pursue, which is credited as S4; it does not evidence authority to redefine the system&#39;s ultimate identity/governance policy at runtime. - Evidence: idea schema and launcher, AgentManager stage contract. - Basis: structural negative finding. - Confidence: high. - Caveats: human selection of the input idea/configuration is not automatically parent-governed S5.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/veritas.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/SakanaAI/AI-Scientist-v2\" target=\"_blank\" rel=\"noopener\">The AI Scientist-v2</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/SakanaAI/AI-Scientist-v2/tree/96bd51617cfdbb494a9fc283af00fe090edfae48\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 96bd51617cfdbb494a9fc283af00fe090edfae48\">96bd516 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform executable ML research experiments through model-driven proposal/code changes, execution and feedback-guided search. - Disturbance / variety regulated: implementation failures, changing metrics/plots, alternative model/data choices, debugging needs and experimental outcomes across tree-search nodes. - Decisive decision or feedback right: choose concrete experiment/code changes and search-node actions based on current task description, parent node/history and execution feedback. - Decision owner: first-party parallel experiment/search agents instantiated by AgentManager. - Supporting / enforcement mechanisms: journals/nodes, experiment executor callbacks, workspace isolation/state, stage-specific task descriptions, search budgets and GPU/process management. - Closure path: research-stage goal/current node -&gt; agent proposes implementation/experiment -&gt; runtime executes it -&gt; metrics/errors/plots are recorded in journal state -&gt; agent/search policy chooses subsequent node/action. - Boundary reachability: the tree-search agents are created and run by the shipped AgentManager used directly by launchscientistbfts.py. - Why this is / is not agent-owned: schedulers/GPU management enforce execution resources, but the context-sensitive experimental action is selected by model-driven agents. - Evidence: README.md, agentmanager.py, parallelagent.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material agent-owned S2 coordination path is established among the parallel S1 search workers. - Disturbance / variety regulated: workers share finite execution resources and contribute nodes to experiment search, but no agent-owned interference/oscillation detector and attenuation relation is established. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: parallel worker scheduling, GPU manager/allocation, journals and tree-search selection. - Closure path: resource/scheduling code assigns/releases execution capacity and search code selects nodes; this is deterministic orchestration rather than an S2 conflict-regulation conversation. - Why this is / is not agent-owned: worker plurality and GPU allocation are not promoted to S2 without an agent-owned response to a concrete inter-S1 disturbance. - Evidence: parallelagent.py, agentmanager.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain a whole-experiment current view and adaptively control stage completion, continuation and next experimental focus on behalf of the research run. - Disturbance / variety regulated: incomplete or unstable implementations, insufficient dataset coverage, weak progress, missing stage criteria, changing best-node evidence and current experimental issues. - Decisive decision or feedback right: judge whether the current sub-stage/stage is complete and generate measurable next sub-stage goals/focus from current experiment evidence; advance or continue the staged research program accordingly. - Decision owner: the model-driven feedback/control queries executed by the first-party AgentManager over its whole current stage/journal state. - Supporting / enforcement mechanisms: stage/journal state, best-node selection, VLM plot feedback, structured completion function schemas, hard bounds/fallback rules, checkpointing and stage-transition machinery. - Closure path: current journals/best node/metrics/plot feedback -&gt; manager control query judges completion or identifies missing criteria -&gt; manager continues current stage or creates a new focused sub-stage/main stage -&gt; subsequent agents receive the revised stage goals and operate under them. - Boundary reachability: AgentManager is instantiated by the standard BFTS experiment path and its run() loop directly creates worker agents and applies the completion/focus decisions. - Why this is / is not agent-owned: fixed stage ordering and max-iteration bounds are deterministic support, but the materially adaptive completion/focus judgments are model queries that change subsequent whole-run experiment commitments. - Whole-system current view: current stage, all stage journals/history, best implementation, success counts/metrics, VLM feedback, tested datasets and current issues/progress at the declared experiment-run recursion. - Current-control decision scope: whether to continue/complete the current stage and what concrete goals/focus the next sub-stage should impose on all subsequent experiment workers. - Evidence: agentmanager.py, performexperimentsbftswithagentmanager.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material complementary audit loop returning sufficiently independent findings into the S3 current-control path is established at the reviewed revision. - Disturbance / variety regulated: VLM plot analysis, multi-seed evaluation and final paper review provide evaluation signals, but their roles do not establish a separate operational audit channel with corrective return to S3. - Decisive decision or feedback right: none established for S3. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: plot/VLM feedback, multi-seed evaluation, LLM text review and image/caption/reference review. - Closure path: VLM/metric feedback is consumed as part of ordinary manager evaluation; final paper reviews are written to files after write-up and are not returned into a correction/re-control loop. - Why this is / is not agent-owned: evaluator agents/models exist, but evaluation naming or separate inference alone is insufficient without a complementary independence-and-corrective-return closure. - Evidence: agentmanager.py, launchscientistbfts.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: sense external literature and prospective scientific opportunity, generate/refine a future research proposal, and return that option into current experiment execution. - Disturbance / variety regulated: prior literature may make ideas non-novel; alternative hypotheses/experiments may differ in feasibility, impact and relation to existing work. - Decisive decision or feedback right: choose search queries, incorporate retrieved literature into reflection, and finalize a structured future proposal/hypothesis/experiment plan. - Decision owner: first-party ideation LLM agent using the shipped Semantic Scholar tool loop. - Supporting / enforcement mechanisms: SemanticScholarSearchTool, action/tool protocol, reflection loop, structured FinalizeIdea schema and JSON handoff to launcher. - Closure path: workshop/topic description -&gt; ideation agent searches external literature -&gt; retrieved results alter reflection/proposal -&gt; agent finalizes structured idea -&gt; launchscientistbfts.py consumes that idea and executes the experiment program. - Boundary reachability: performideationtempfree.py is the documented first step for generating the JSON consumed by the standard experiment launcher. - Why this is / is not agent-owned: the search tool supplies evidence, but the prospective research-option synthesis and finalization are agent decisions. - External distinction: Semantic Scholar literature and related-work evidence. - Future / prospective distinction: novelty, feasibility, risks and which hypothesis/experiments should be pursued next. - Adaptation option generated: structured research proposal containing hypothesis, related work, experiments and limitations. - Path back into current capability / S3: generated idea JSON becomes the task description for AgentManager and its experiment stages. - Evidence: performideationtempfree.py, README.md, launchscientistbfts.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: workshop/topic descriptions, stage goals, risk-factor prompts, model choices and BFTS configuration constrain research, but they do not form an identity-level ultimate-authority loop. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: workshop description, proposal schema, hard-coded main-stage goals, YAML search configuration and CLI arguments. - Closure path: configuration/prompt policy directly constrains the run; no identity/ultimate-policy issue is escalated to an authoritative actor and returned as governing policy. - Why this is / is not agent-owned: the agent manager can adapt current experimental focus, but it is not given authority to redefine the system&#39;s identity or ultimate research policy. - Evidence: agentmanager.py, performideationtempfree.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/ai-scientist-v2.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/SakanaAI/AI-Scientist\" target=\"_blank\" rel=\"noopener\">The AI Scientist</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/SakanaAI/AI-Scientist/tree/1de1dbc1f4ee2c5f61e9c94348d55eb51d7fa2eb\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1de1dbc1f4ee2c5f61e9c94348d55eb51d7fa2eb\">1de1dbc &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously implement and execute research experiments and produce the resulting scientific artifacts within a maintained experiment template. - Disturbance / variety regulated: code/runtime errors, differing experimental ideas, metric outcomes, plotting/write-up needs and project-file state. - Decisive decision or feedback right: choose concrete experiment/code edits and subsequent actions based on the idea, baseline state and observed execution/results. - Decision owner: the active model-driven Aider coding/experiment agent used by the first-party experiment loop. - Supporting / enforcement mechanisms: copied per-idea workspace, baseline results, performexperiments, Aider file editing, process execution, notes/logs and bounded experiment flow. - Closure path: idea/baseline/workspace -&gt; agent edits experiment implementation -&gt; code executes -&gt; result/error evidence returns -&gt; agent chooses further experiment edits or completion. - Boundary reachability: the loop is invoked by the documented launchscientist.py entrypoint for every novel idea in a standard paper-generation run. - Why this is / is not agent-owned: Python launcher logic enforces sequencing, but the context-sensitive experiment/code choices are model-agent decisions. - Evidence: launchscientist.py, README.md, aiscientist/performexperiments.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established. - Disturbance / variety regulated: multiple ideas may execute in parallel on different GPUs, but the workers are independent attempts; no concrete cross-S1 conflict/oscillation and attenuation relation is evidenced. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: multiprocessing queue, GPU assignment and independent per-idea workspaces. - Closure path: scheduling distributes independent jobs; it does not return a coordination decision to change behavior because of inter-S1 interference. - Why this is / is not agent-owned: resource scheduling is deterministic runtime support and parallelism alone is not S2. - Evidence: launchscientist.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no agent-owned whole-system current-control function is established. - Disturbance / variety regulated: failures/success at experiment/write-up/review stages change control flow, but stage ordering and stop/advance rules are fixed by the launcher. - Decisive decision or feedback right: no autonomous actor is shown holding a whole-run current view and discretionary authority over current shared resources, commitments, priorities or constraints. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: launcher stage sequence, exceptions/return values, GPU/process setup, skip/improvement flags and fixed success gates. - Closure path: deterministic success/failure and CLI configuration drive stage transitions. - Why this is / is not agent-owned: local agents decide experiments/write-up content, while whole-run control remains scripted. - Evidence: launchscientist.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge the produced research manuscript and, in the supported improvement mode, return findings into a separate corrective write-up path. - Disturbance / variety regulated: unsupported/unclear claims, presentation weaknesses, methodological weaknesses and other defects observable by a paper reviewer but not necessarily corrected during ordinary write-up. - Decisive decision or feedback right: produce a structured peer-review judgment/weakness set over the completed paper; those findings become explicit corrective input in improvement mode. - Decision owner: the first-party automated paper-review invocation, separate from the Aider writer/coder session being reviewed. - Supporting / enforcement mechanisms: PDF loading, review ensemble/reflections, persisted review.txt, performimprovement, PDF regeneration and second review. - Closure path: writer produces PDF -&gt; separate reviewer evaluates it -&gt; structured review/weaknesses -&gt; performimprovement(review, coder) returns findings to writer/coder -&gt; revised PDF -&gt; reviewer evaluates the revised artifact again. - Boundary reachability: --improvement is an explicit supported launcher mode using first-party review and improvement functions; it requires no external custom orchestration beyond normal model credentials. - Why this is / is not agent-owned: the reviewer owns the semantic challenge judgment; the launcher only transfers review findings and enforces the second pass. - Claim being audited: that the research manuscript adequately presents/supports the generated scientific work at peer-review quality. - Ordinary reporting path: experiment notes/results -&gt; manuscript generation by the coding/writing agent. - Complementary access path: a separate review invocation reads the rendered paper and evaluates it with a review-specific prompt/ensemble rather than reusing the writer conversation. - Independence boundary: writer/coder and reviewer are separate model interactions/roles; review is generated after the artifact is materialized. - Who acts on findings: the Aider writer/coder through performimprovement, followed by manuscript regeneration. - Evidence: launchscientist.py, aiscientist/performreview.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: generate prospective research options, interrogate external literature for novelty and return novel ideas into current experimentation. - Disturbance / variety regulated: existing prior work may make a candidate idea non-novel; alternative ideas differ in feasibility/interestingness and should change the next experiment attempted. - Decisive decision or feedback right: propose/refine research ideas and, during novelty checking, choose literature queries and decide whether each idea is novel enough to enter the experiment set. - Decision owner: first-party idea-generation/novelty-checking model agents. - Supporting / enforcement mechanisms: idea reflection archive, Semantic Scholar/OpenAlex search, structured idea JSON, novelty flag and launcher filtering to novelideas. - Closure path: template/task context -&gt; agent proposes/refines idea -&gt; external literature searches return evidence -&gt; novelty judgment marks idea -&gt; only novel ideas are dispatched into executable experiments. - Boundary reachability: idea generation and novelty checking are invoked by the standard launcher unless explicitly skipped; their JSON/novelty outputs directly gate experiment admission. - Why this is / is not agent-owned: search APIs provide external observations, but query selection, idea refinement and novelty judgment are model-agent decisions. - External distinction: retrieved titles/abstracts/metadata from Semantic Scholar or OpenAlex. - Future / prospective distinction: whether a proposed idea is sufficiently novel/feasible/interesting to justify a future experiment. - Adaptation option generated: structured experiment idea with title, experiment outline and quality ratings. - Path back into current capability / S3: launcher filters ideas to novelideas and runs each accepted idea through doidea experiment/write-up execution. - Evidence: aiscientist/generateideas.py, launchscientist.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: experiment templates, prompt/task descriptions, model/engine flags and safety/container advice constrain operation, but no identity-level issue is routed to an ultimate authority. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: template prompt.json, CLI options, maintained template structure and static safety guidance. - Closure path: configuration/prompt/template policy directly constrains work; no identity/ultimate-policy decision loop is evidenced. - Why this is / is not agent-owned: research agents can select ideas/experiments but do not own authority to redefine the system&#39;s organizational identity or ultimate policy. - Evidence: README.md, launchscientist.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/ai-scientist.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-26T23:48:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/nsidn98/LLaMAR\" target=\"_blank\" rel=\"noopener\">LLaMAR</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-26\">2026-09-26</time></td><td class=\"review-ref\"><a href=\"https://github.com/nsidn98/LLaMAR/tree/d2b74cac79a0f070d87a150712f8e2ae174920be\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision d2b74cac79a0f070d87a150712f8e2ae174920be\">d2b74ca &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute the embodied work required to complete the shared task through robot-specific actions in the environment. - Disturbance / variety regulated: partial observations, object locations/states, navigation/manipulation requirements, action failures and changing environment state during a long-horizon episode. - Decisive decision or feedback right: choose each robot&#39;s next substantive environment action from the current observations/state and interpret returned success/failure when selecting what happens next. - Decision owner: the first-party model-driven LLaMAR action/controller path over the embodied robot streams. - Supporting / enforcement mechanisms: AI2-THOR/SAR environment adapters, feasible-action mapping, per-agent observations/states/action histories, task/subtask state and deterministic execution plumbing. - Closure path: team task/current plan -&gt; model selects an action for each robot -&gt; environment executes each embodied action -&gt; per-agent observation/state/success/failure returns -&gt; later model call selects changed robot actions -&gt; episode progresses. - Boundary reachability: AI2Thor/baselines/llamar/llamar.py and SAR/baselines/llamar.py are shipped runnable first-party episode entrypoints and directly execute the credited action/environment feedback loop. - Why this is / is not agent-owned: simulator code transports actions and state, while the substantive next-action choices are model-generated from the live episode context. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/envnew.py; SAR/baselines/llamar.py. - Basis: explicit + structural. - Confidence: high. - Caveats: next-action authority is centralized in the model call rather than separately modelled inside each physical robot, but the operational behavior is still first-party agent-owned at the assessed team boundary.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate concrete interference among simultaneously operating embodied robots sharing the same physical workspace. - Disturbance / variety regulated: robots blocking/bumping one another, congestion around shared objects/receptacles, one robot&#39;s manipulation/navigation preventing another robot from completing its assigned action, and unnecessary simultaneous movement into the same constrained area. - Decisive decision or feedback right: choose joint next-step actions such as waiting, moving aside, closing an obstruction or delaying one robot so another robot can proceed without cross-agent interference. - Decision owner: the first-party model-driven joint action/controller path using whole-team state and failure context. - Supporting / enforcement mechanisms: shared observations/state, previous action/failure fields, combined task/memory state, explicit anti-blocking prompt constraints and per-robot joint action output. - Closure path: multiple robot operations interact in one room -&gt; execution exposes cross-agent blocking/failure -&gt; the next model call reasons about the interference -&gt; assigns compensating actions across the involved robots -&gt; later robot behavior changes and the blocked operation can proceed. - Boundary reachability: the standard LLaMAR actor prompt is called on every episode step from the runnable baseline and directly receives/returns the team state and per-agent joint actions used by env.step(). - Why this is / is not agent-owned: the anti-interference choice is contextual model reasoning over current cross-agent state; deterministic code only executes the selected joint actions. - Evidence: AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/baselines/llamar/llamar.py; AI2Thor/envnew.py. - Basis: explicit + structural. - Confidence: high. - Caveats: generic task allocation is not the basis for S2; the positive state rests on the separately evidenced physical interference problem and feedback relation. - Distinct S1 units: the concurrently acting embodied robot streams (Alice, Bob and additional configured robots), each with its own observation/state/action/success history and physical action effect. - Inter-S1 disturbance: one robot can physically block/bump another or occupy/open an object/path such that another robot&#39;s navigation/manipulation fails or must wait. - Attenuating coordination relation: the joint controller sees all robots&#39; state/history and is explicitly instructed to avoid blocking/bumping; failure reasoning can prescribe wait/move-aside/clear-path behavior across the involved robots. - Feedback into subsequent S1 behaviour: the model&#39;s coordinated per-robot action dictionary is passed through actionchecker and then to env.step(), changing the next embodied action of each robot. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the decisive witness is regulation of a concrete interaction disturbance among simultaneous embodied operations, not the existence of multiple robots, shared memory or a task decomposition graph.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain the whole team&#39;s current task commitments and intervene in the active multi-robot plan as completion/failure/environment information changes. - Disturbance / variety regulated: changing team progress, completed versus still-open commitments, newly observed environment information and failures requiring the active plan or current robot allocation/actions to change. - Decisive decision or feedback right: decide the current shared open-subtask plan for the team and, through the whole-team action/controller stage, determine which operational action each robot should take now under that plan. - Decision owner: the first-party model-driven planner and whole-team action/controller path. - Whole-system current view: the planner receives the task, current observation from every configured robot, and the shared open/completed subtask state after each verifier step; the action/controller additionally receives every robot&#39;s state, previous action/failure, shared subtasks and combined memory. - Current-control decision scope: preserve or revise the team&#39;s active unfinished commitments and assign the next concrete actions/subtasks across the current robot population, including interventions after failures and current spatial conflicts. - Supporting / enforcement mechanisms: shared open/completed-subtask state, verifier updates, whole-team observation aggregation, combined memory, planner prompt, action/controller prompt and repeated plan-update loop. - Closure path: robot operations execute -&gt; team observations/actions and completion state update -&gt; verifier updates completed commitments -&gt; planner forms a revised whole-team open plan -&gt; action/controller maps that current plan/state to robot-specific next actions -&gt; changed operations execute and report back. - Boundary reachability: the planner/action stages are invoked in every standard runnable LLaMAR episode; no external orchestrator is required to form the whole-team view or return interventions into robot operation. - Why this is / is not agent-owned: the semantic choice of the current plan and per-robot intervention is model-driven; deterministic code stores plan/completion state and transports decisions into the environment. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/envnew.py; SAR/baselines/llamar.py. - Basis: explicit + structural. - Confidence: high. - Caveats: S3 credit is not based on the component name Planner; it rests on the whole-team current view plus returned decisions changing the active shared commitments and robot actions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: the verifier provides in-band completion reporting, but no materially independent complementary-audit function is established. - Disturbance / variety regulated: incorrect assumptions about whether a subtask has completed can be corrected before replanning, but the checked claim remains part of the ordinary task-progress loop. - Decisive decision or feedback right: no independent auditor with a distinct authority/evidence channel is established; the verifier prompt only classifies completed subtasks for the same episode. - Decision owner: none established for qualifying S3; the verifier uses the ordinary model service/configuration and shared episode evidence. - Supporting / enforcement mechanisms: verifier-specific prompt, all robot observations/states/previous actions, shared open/completed subtasks and combined memory. - Closure path: robot actions execute -&gt; ordinary episode observations feed verifier -&gt; completed-subtask list feeds planner -&gt; current plan changes; this is ordinary progress reporting/monitoring without an evidenced independent audit boundary. - Why this is / is not agent-owned: a semantic verifier exists, but verifier naming and a separate prompt-stage do not establish complementary independence. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/envnew.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: the verifier does influence subsequent planning; the missing requirement is organizational/complementary independence, not lack of feedback.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party prospective capability-adaptation loop is established beyond current-episode planning/replanning. - Disturbance / variety regulated: LLaMAR adapts its current task plan to new observations and failures, but does not evidence an actor that senses an external future environment, generates capability-change options and installs a change for later operational capability. - Decisive decision or feedback right: none established for prospective adaptation of the installed harness/robot organization across episodes. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: current observation updates, planner replanning, memory and failure reasoning. - Closure path: environment change/failure -&gt; current episode replanning -&gt; changed immediate robot actions; no future-oriented capability option is implemented into later installed capability. - Why this is / is not agent-owned: current replanning is S1/S3 regulation, not evidence of S4 merely because the plan changes. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; README.md. - Basis: structural negative search. - Confidence: high. - Caveats: long-horizon planning and replanning are substantial capabilities but remain inside the present episode boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity or ultimate-policy authority is established at the multi-robot episode boundary. - Disturbance / variety regulated: task text, model/configuration parameters, prompt rules and simulator limits constrain behavior but do not constitute identity-level adjudication. - Decisive decision or feedback right: none established for defining or reconciling the team&#39;s ultimate identity/purpose/policy under competing S3/S4 demands. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: user-selected task/scene/configuration, static prompts and runtime constraints. - Closure path: external task/configuration enters directly as operating constraints; no identity-level issue -&gt; legitimate ultimate authority -&gt; policy decision -&gt; returned governance loop is evidenced. - Why this is / is not agent-owned: the models control current operational/coordination/management choices but do not choose the organization&#39;s ultimate identity or policy. - Evidence: README.md; AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py. - Basis: structural negative search. - Confidence: high. - Caveats: static system prompts describing robot roles/constraints are not S5 by themselves.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a6735e44e0989bceeb433c4133d76671108cc563/assessments/llamar.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a6735e44e0989bceeb433c4133d76671108cc563\">a6735e4 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-10-27T16:28:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/DemonDamon/AgenticX\" target=\"_blank\" rel=\"noopener\">AgenticX</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-27\">2026-10-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/DemonDamon/AgenticX/tree/582c9d00bfb23efe6f7e588c3a5edfce570729bf\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 582c9d00bfb23efe6f7e588c3a5edfce570729bf\">582c9d0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform open-ended user tasks by choosing tools, using execution results, and modifying task artifacts through root/child provider-backed agent sessions. - Disturbance / variety regulated: new task details, tool errors, repository content, provider responses and subtask outcomes. - Decisive decision or feedback right: choose next model tool call, interpret feedback and continue/revise an execution plan. - Decision owner: configured model-backed AgentRuntime/ReAct root and spawned agents; neither the SDK Agent data model nor the event queue owns model reasoning. - Supporting / enforcement mechanisms: provider resolver, agent/tool loop, Studio session persistence, subagent context/tool permissions and callbacks. - Closure path: model chooses a tool, runtime executes it, the result enters the same agent&#39;s context, and later decisions change task output. - Boundary reachability: this path is shipped both through the agx/Studio local backend and embedded SDK; Near&#39;s default app starts this local runtime. - Why this is / is not agent-owned: the agent model makes contextual tool/continuation decisions; host code supplies guardrails and transport. - Evidence: AgentRuntime, ReActAgent, Studio server Meta-Agent setup. - Basis: explicit and structural. - Confidence: high. - Caveats: successful live provider/model execution and claimed production quality were not measured.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no evidence-backed distinct relation that autonomously attenuates an identified interference among simultaneously acting S1 units, beyond task partition and bounded queueing. - Disturbance / variety regulated: potential overlap of parallel workers, resource contention and conflicting changes would require interference-specific handling. - Decisive decision or feedback right: no first-party agent-owned cross-worker conflict detection, reconciliation or isolation decision shown as an operationally closed coordination loop for the declared Studio team. - Decision owner: none established at S2; the model planner assigns tasks and host TaskLock transports actions. - Supporting / enforcement mechanisms: Team task decomposition, worker assignments/dependencies, TaskLock action queue, group routing and shared context. - Closure path: delegations can complete and summaries return, but that is ordinary task routing; no distinct detected inter-S1 collision and corrective relation is evidenced. - Why this is / is not agent-owned: naming a CoordinatorAgent or serializing actions does not establish function-specific S2 conflict attenuation. - Distinct S1 units: concurrent model-backed child agents. - Inter-S1 disturbance: same-file edits or contested resources are plausible, but the inspected supported team path does not independently establish a response to an observed conflict. - Attenuating coordination relation: no qualifying inter-S1 relation established; task lists and a queue prevent generic scheduling races, not semantically competing work ownership. - Feedback into subsequent S1 behaviour: worker results and messages return to the manager/leader, but without a verified conflict-specific control decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: S2-specific ownership is not credited for generic dispatch or action queue operations. - Evidence: Team mode wiring and TaskLock, TaskLock, WorkforcePattern. - Basis: structural. - Confidence: medium. - Caveats: developers may compose custom S2 adapters with the SDK; that is not automatically the shipped Studio default.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: supervise the current root-session team by observing children and deciding when to spawn, communicate, retry or cancel during live task delivery. - Disturbance / variety regulated: active child runs may stall/fail, saturate concurrency or CPU/memory, need new work or require intervention to meet the immediate user task. - Decisive decision or feedback right: select and invoke status query, spawn/cancel/retry/message subagent tools in light of reported current child state and goals. - Decision owner: configured root model-backed Meta-Agent within the supported Studio session, not the AgentTeamManager or the deterministic ResourceMonitor. - Supporting / enforcement mechanisms: AgentTeamManager actual live status registry, timeouts, caps and resource admission checks; root Meta-Agent tool dispatcher; Studio event stream. - Closure path: root sees team status/tool results, chooses a current-team intervention, AgentTeamManager changes a child run/permission to launch, and updated state returns to the root&#39;s next model turn. - Boundary reachability: Studio builds the root Meta-Agent with visible team-management tools, and the attached AgentTeamManager executes them on real session children in the shipped local backend. - Why this is / is not agent-owned: current worker-team decisions are controlled by the root model, while deterministic caps merely reject inadmissible actions. - Whole-system current view: querysubagentstatus and team status provide running/completed/failed child state and resource-monitor context for the session team. - Current-control decision scope: the current portfolio of active/retryable child agents in one root session, including admission and cessation; not Enterprise gateway quotas or an unrelated Studio user. - Evidence: team lifecycle/status/cancel, meta tool handler, resource monitor. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: the model might choose not to use these tools; the claim is an available integrated operational loop, not a guaranteed policy of continuous proactive optimization.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no independently controlled complementary reality-audit path with corrective control established for the current Studio session team. - Disturbance / variety regulated: an executor can mistakenly report complete work while the real environment differs. - Decisive decision or feedback right: no independent auditor&#39;s direct-evidence veto/intervention against the team report established in the selected operating mode. - Decision owner: none established; SDK evaluation/LLM judge and Enterprise audit logging are separate or routine surfaces. - Supporting / enforcement mechanisms: traces, tool results, observability and optional evaluation framework. - Closure path: tests/evaluations can be explicitly launched, but a first-party independently owned standing complementary team audit with returned corrective control is not demonstrated. - Why this is / is not agent-owned: evaluation APIs, group worker results and log chains cannot substitute for a separate auditor owner. - Evidence: evaluation/observability overview, team results, Enterprise gateway separation. - Basis: structural. - Confidence: medium. - Caveats: externally composed independent reviewers are possible through the SDK, but their independence cannot be credited to the shipped session team.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: convert observations of changing external tool/provider/task conditions and user corrections into future reusable skill capability for subsequent sessions. - Disturbance / variety regulated: repeated external tool failures, newly learned environment conventions and multi-step strategies that existing installed skills do not yet encode. - Decisive decision or feedback right: the background model-backed review agent decides whether and how to create/patch a reusable skill; under the normal supervised mode the Desktop operator separately decides whether to approve the proposed future capability. - Decision owner: opt-in skill-review agent in the direct-authorized mode (A), and legitimate Desktop-user approver for a separately supported queued-proposal mode (P). These modes are not simultaneous autonomous governance. - Supporting / enforcement mechanisms: registered SessionReviewHook, actual tool observation records, signal/complexity gate, configured review model, skillmanage, skill policy scan, pending proposals and desktop approval endpoint. - Closure path: a completed tool-using session triggers a review of observed attempts/errors/user corrections; the model proposes a skill; in explicitly authorized direct mode it writes the skill for later sessions, while in default queue mode the Desktop user approves the same proposed document and installs it. Later model runs can discover/use the changed skill collection. - External distinction: observations concern user corrections and tool/provider outcomes from the task environment, not just the host runtime&#39;s own counters; the model interprets their reusable implications. - Future / prospective distinction: a post-session reviewer encodes a method for later task contexts rather than repairing only the completed current task, and the installed skill survives that session boundary. - Adaptation option generated: choose a new action-oriented skill or a patch to an existing skill, including the specific steps and guardrails for future comparable disturbances. - Path back into current capability / S3: after authorized direct installation or Desktop-user approval, the skill is added to the local installed registry so a later Meta-Agent/runtime session can discover and use the revised capability under its current task controls. - Boundary reachability: AgentRuntime registers SessionReviewHook; learning.reviewenabled is an active shipped configuration option, agentwritesrequireapproval distinguishes queue versus direct install, and Studio/Near expose proposal inspection/approve/reject routes. Both paths require configured model/provider access; neither is default-on just because observation is enabled. - Why this is / is not agent-owned: the reviewer model selects substantive future reusable methods, not just a deterministic score; the operator retains the separate approval right in the supervised mode.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no closed ultimate-purpose or identity-policy governance path for the local Studio agent-team recursion. - Disturbance / variety regulated: conflicts about the team&#39;s permanent charter, legitimacy or non-negotiable identity beyond ordinary tasks/permissions. - Decisive decision or feedback right: no runtime identity-level final authority and returned policy choice established in the selected local session hierarchy. - Decision owner: none established for this function; product maintainers, Enterprise administrators and local user are adjacent authorities for different matters. - Supporting / enforcement mechanisms: operator permissions, skill-approval gate, safety policies, user prompts, Enterprise Gateway policies and contributor governance. - Closure path: users permit/deny operations, administrators configure Gateway routing, and skill approvals modify future capabilities; these are operational/safety/adaptation choices rather than a reconstructed identity-level decision loop in local Studio. - Why this is / is not agent-owned: a Meta-Agent CEO label does not create sovereign identity control, and separate enterprise governance does not transfer to deployed Studio S5. - Evidence: runtime/Enterprise boundaries, Studio tool gates, Meta-Agent identity prompt. - Basis: structural. - Confidence: medium. - Caveats: no finding about how the open-source project or enterprise tenants should normatively govern themselves is made.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d83ab15f2643bc53884a269c9555beaea45091fb/assessments/ag/agenticx.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d83ab15f2643bc53884a269c9555beaea45091fb\">d83ab15 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-29T17:45:27Z\"><th scope=\"row\"><a href=\"https://github.com/pipecat-ai/pipecat\" target=\"_blank\" rel=\"noopener\">Pipecat</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-29\">2026-09-29</time></td><td class=\"review-ref\"><a href=\"https://github.com/pipecat-ai/pipecat/tree/dbdf21a017f86624fb7768e35730417169524e0d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision dbdf21a017f86624fb7768e35730417169524e0d\">dbdf21a &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform an environment-facing conversational/agent task by selecting model responses and model-callable tools from live input/context and incorporating tool/service outcomes into subsequent operation. - Disturbance / variety regulated: user utterances, conversation state, tool needs/results, external-service responses, media events and task-specific runtime outcomes. - Decisive decision or feedback right: choose the substantive next response/tool action in the shipped model/tool loop. - Decision owner: the configured LLM actor invoked through Pipecat&#39;s first-party LLM service/pipeline surfaces. - Supporting / enforcement mechanisms: context aggregators; tool schemas/callbacks; transports; pipeline frames; jobs; timeouts; service adapters; tracing/metrics. - Closure path: user/environment input enters pipeline → Pipecat constructs model context/tools → model chooses response/tool action → runtime executes/delivers it → observations/results are returned into later context and operation. - Boundary reachability: this is Pipecat&#39;s ordinary supported runtime, not a repository-development-only example. - Why this is / is not agent-owned: removing the model decision actor leaves transport/execution machinery but removes the open-ended choice of conversational/task action. - Evidence: README.md; llmworker.py; openclaw-agent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: provider implementation is external, but Pipecat deliberately places the model actor inside its supported operational feedback loop.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate concurrent/interleaved output interference between distinct autonomous LLM workers during a live handoff and ensure that only the selected worker owns the next conversational operation. - Disturbance / variety regulated: the target worker can begin producing while the source worker still has output in flight, causing both workers&#39; outputs to arrive interleaved; overlapping activation would make ownership of the user-facing turn ambiguous. - Decisive decision or feedback right: decide when to transfer conversational ownership from the current autonomous worker to another worker in response to the live conversation. - Decision owner: the currently active LLM worker in the first-party local-handoff mode, through the model-callable transfertoagent tool. - Supporting / enforcement mechanisms: activateworker; source-pipeline drain; mutually exclusive activation/deactivation; shared worker registry/bus; tool result that suppresses another current LLM run during transfer. - Closure path: current LLM observes conversation → model selects transfertoagent → source worker drains outstanding output → runtime deactivates source and activates target without overlap → subsequent user-facing operation is produced by the selected target worker. - Boundary reachability: the behavior is implemented by first-party worker APIs and exercised by a runnable first-party multi-worker example whose documentation explicitly states that the LLM decides when to transfer. - Distinct S1 units: the active greeter/customer-service LLMWorker and the target support LLMWorker are separate model-driven operational workers sharing the conversation transport through the worker runtime. - Inter-S1 disturbance: without handoff drainage/exclusivity, the target worker can begin producing while the source worker still has output in flight, and both outputs can arrive interleaved. - Attenuating coordination relation: activateworker drains the source pipeline, deactivates it, then activates the selected target so the two workers do not simultaneously own user-facing output. - Feedback into subsequent S1 behaviour: after the model-selected handoff, the target worker becomes active and receives/acts on subsequent conversation turns while the source is inactive. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the mechanism exists to attenuate a documented interference between two autonomous operational workers, and its result changes their subsequent operational participation; credit does not rely on WorkerBus messaging or delegation alone. - Why this is / is not agent-owned: the runtime enforces safe switching, but the semantic choice of when/where to transfer is made by the active model from live conversational evidence. Removing that model decision leaves a callable handoff primitive, not the same coordination judgment. - Evidence: local-handoff-two-agents.py; worker.py; baseworker.py. - Basis: explicit + structural. - Confidence: high. - Caveats: generic WorkerBus messaging/job routing is not used as S2 evidence; credit depends on the concrete interleaving disturbance and the model-selected handoff closure.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the current subordinate agent commitment while preserving a responsive voice/conversation loop. - Disturbance / variety regulated: long-running delegated work can be idle, active, obsolete after a user correction, redirected, cancelled, failed or completed while the conversational front end continues receiving new input. - Decisive decision or feedback right: from live subordinate-job state, choose whether to dispatch/update work, inspect current status or preemptively stop the active subordinate commitment. - Decision owner: the voice LLM in the first-party OpenClaw-agent composition; its context exposes sendtoagent, stopagent and agentstatus as model-callable tools. - Supporting / enforcement mechanisms: ActiveJob; bus job requests/updates/responses; job-group cancellation; WorkerRunner; OpenClaw worker; developer messages that return job outcomes to the voice model. - Closure path: voice LLM receives current user input plus returned job state/outcome → model chooses direct response or a current-control tool → Pipecat dispatches/updates, reports or cancels the subordinate job → bus update/response changes ActiveJob and is returned to the voice loop → later current-control decisions use the changed state. - Boundary reachability: the complete path is a runnable first-party multi-worker example built on public first-party worker/job APIs. - Whole-system current view: at the selected voice-plus-agent recursion, the voice regulator tracks the only subordinate operational commitment (jobid, request, start time and later response/update state) while continuing its own user-facing work. - Current-control decision scope: it can create/change the live delegated commitment and preempt it; this is stronger than read-only status or runtime lifecycle cleanup. - Why this is / is not agent-owned: the LLM itself selects the exposed dispatch/status/stop tools from current conversational evidence. Runtime code transports/enforces those choices; it does not make an equivalent semantic judgment when the model is removed. - Evidence: openclaw-agent/README.md; openclaw-agent.py; runner.py. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: the OpenClaw backend decides whether a forwarded update starts a new internal turn or steers an existing one. S3 credit is not assigned to that backend decision; it is assigned to Pipecat&#39;s model-facing authority to observe, issue/update and cancel the current subordinate commitment at this recursion. Generic WorkerRunner end/cancel behavior alone would be constructor lifecycle support, not agent-owned S3.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary audit loop was established that independently inspects current operational claims and returns findings into the live operation/current-control loop for corrective work. - Disturbance / variety regulated: Pipecat can evaluate bot conversations and report assertion/judge failures, but those evaluation outcomes are separate test/eval results rather than a shipped production correction loop. - Decisive decision or feedback right: not established for S3 at the assessed runtime boundary. - Decision owner: not applicable. - Supporting / enforcement mechanisms: scripted and simulated eval drivers; optional EvalJudge; expectation matching; pass/fail result objects; traces; ordinary worker job responses/errors. - Closure path: no S3-specific corrective closure established. Eval failures can stop or continue an evaluation scenario and are reported to the evaluator/caller, but the reviewed runtime does not feed a distinct auditor finding back into the audited bot&#39;s current work to require revision/retry. - Why this is / is not agent-owned: a separate judge exists, but independence alone is insufficient; the missing production feedback closure prevents classification as A or C S3. - Evidence: scriptdriver.py; simulation.py; openclaw-agent.py. - Basis: explicit + structural negative finding. - Confidence: high. - Caveats: downstream applications can consume eval failures and implement corrective loops; caller composition is not credited as first-party Pipecat closure without shipped wiring.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective adaptation loop was established that converts environmental distinctions into persistent changes of Pipecat operating capability/policy used by later work. - Disturbance / variety regulated: persistent conversation memory and dynamic current-session flow/context exist, but no reviewed mechanism closes prospective capability adaptation. - Decisive decision or feedback right: not established for S4. - Decision owner: not applicable. - Supporting / enforcement mechanisms: Mem0 message storage/search; LLM conversation context; flow transitions and role messages; runtime LLM settings updates; session continuation. - Closure path: no S4-specific closure established. Mem0 stores user/assistant messages and retrieves relevant memories into later context; it does not itself decide or persist a changed skill/tool/policy/capability in response to external/future distinctions. - Why this is / is not agent-owned: memory continuity and current-flow reconfiguration can affect future responses, but the reviewed first-party code does not contain the required sensing → prospective adaptation judgment → persistent capability change → reuse loop. - Evidence: memory.py; flows/manager.py; llmcontext.py. - Basis: explicit + structural negative finding. - Confidence: high. - Caveats: a downstream agent can use Pipecat tools to build its own learning/adaptation system; that is outside this standalone runtime assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy loop with legitimate ultimate authority and returned closure was established at the assessed recursion. - Disturbance / variety regulated: bots can have durable system instructions, role messages and application-authored rules, but these are configured operating instructions rather than an S5 adjudication loop. - Decisive decision or feedback right: an S5 witness would require an unresolved identity/ultimate-policy issue to reach a legitimate parent/ultimate authority and the resulting policy decision to return into later operation; no such first-party path was established. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: configured systeminstruction; Flow rolemessage; tool schemas; application code; provider/session settings. - Closure path: no S5-specific escalation-and-return path established. Pipecat can apply or update instructions supplied by the application, but that is instruction transport/current configuration rather than ownership of identity or ultimate policy. - Why this is / is not agent-owned: neither static developer-authored identity nor runtime system-instruction mutation by framework/application code establishes a legitimate ultimate-policy decision loop under Profile 0.2.4. - Evidence: flows/manager.py; llmservice.py; uiworker.py. - Basis: explicit + structural negative finding. - Confidence: high. - Caveats: downstream product owners may govern bot identity out of band; this assessment does not convert arbitrary application configuration into Pipecat S5 ownership.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2f9af52d3fefcbb27eb35f8f736f06a8ef93e432/assessments/pipecat.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2f9af52d3fefcbb27eb35f8f736f06a8ef93e432\">2f9af52 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/microsoft/autogen\" target=\"_blank\" rel=\"noopener\">Microsoft AutoGen AgentChat</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/microsoft/autogen/tree/027ecf0a379bcc1d09956d46d12d44a3ad9cee14\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 027ecf0a379bcc1d09956d46d12d44a3ad9cee14\">027ecf0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: stateful agents choose tools/actions and incorporate returned results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: team selection plus Magentic-One&#39;s explicit loop/stall detection and controlled transfer of the next action right suppress uncontrolled repetition/interference among multiple S1 participants. This is more than mere delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: MagenticOneOrchestrator owns a whole-team current facts/plan/progress ledger and has authority to assess progress, choose commitments, reset participants and regenerate the plan when the team stalls. Code-execution approval constrains an operational executor action rather than independently owning this whole-team current-control loop, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the progress ledger is part of the same operational S3 regulator that directs the team. It is not a distinct complementary audit channel with separate reviewing independence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: replanning after current-task stalls is inside-now adaptation. No distinct external/prospective intelligence function shaping future organizational posture is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: participant set, instructions, termination rules and ultimate authority remain application/parent-owned.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/autogen-agentchat.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper\" target=\"_blank\" rel=\"noopener\">data-to-paper</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper/tree/81df14c4b9600466e645c3b2b336cc54daa3df3a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 81df14c4b9600466e645c3b2b336cc54daa3df3a\">81df14c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform the environment-facing scientific work needed to transform project data and research state into executable analyses and research artifacts. - Disturbance / variety regulated: heterogeneous datasets, generated-code errors, unexpected outputs/files, statistical-analysis requirements, intermediate product state and manuscript construction requirements. - Decisive decision or feedback right: choose and revise analysis/code/content actions in response to current project products, execution results and validation/reviewer feedback. - Decision owner: the active first-party performer/code-writing agents in the hypothesis-testing workflow. - Supporting / enforcement mechanisms: stage runner, CodeRunner, debugger conversers, code extract/check logic, output requirements, product store, data chaining and configured iteration bounds. - Closure path: current scientific products/data -&gt; agent proposes code/content action -&gt; first-party runner executes/materializes it -&gt; output/error/product state returns -&gt; agent revises or advances. - Boundary reachability: these paths are the shipped hypothesis-testing research workflow invoked by the installable application/CLI, not benchmark-only examples. - Why this is / is not agent-owned: runtime and guardrails execute/check code, but the context-sensitive analysis/content choice and revision remain model-agent decisions. - Evidence: README.md, stepsrunner.py, requestcode.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established at the reviewed recursion. - Disturbance / variety regulated: the workflow contains multiple performer/reviewer roles and research stages, but no concrete interference, conflict or oscillation among distinct S1 units is identified and attenuated by a dedicated coordination relation. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: typed stage transitions, product passing, paired conversations, deterministic sequencing and rewind/retry utilities. - Closure path: these mechanisms sequence work and transmit review feedback; they do not close a cross-S1 interference-regulation loop. - Why this is / is not agent-owned: interacting agents and state transfer are real, but the reviewed paths are production/review dependencies rather than S2-specific conflict attenuation. - Evidence: stepsrunner.py, dualconverser.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no autonomous whole-system inside-and-now control function is established at the reviewed recursion. - Disturbance / variety regulated: stage completion, retries, rewinds, project parameters and review rounds constrain current work, but no first-party autonomous actor is shown holding a whole-project current view plus broad authority over shared resources/commitments/priorities. - Decisive decision or feedback right: stage flow and retry bounds are primarily encoded in deterministic runner logic and project parameters; local reviewers control product acceptance rather than organization-wide current control. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: DataStepRunner/HypothesisTestingStepsRunner, stage enums, product readiness, retry/rewind helpers, project parameters and UI actions. - Closure path: configured stage/retry conditions alter control flow mechanically; no discretionary whole-system S3 owner is evidenced. - Why this is / is not agent-owned: model agents make local scientific/product decisions, while the broader workflow sequence is framework-defined. - Evidence: stepsrunner.py, README.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: provide a separate challenge channel that reviews scientific/code/writing products and returns concrete corrective feedback before those products are accepted. - Disturbance / variety regulated: plausible-but-wrong analysis outputs, code/result problems, weak hypotheses/plans, writing defects and other product claims that ordinary performer generation may miss. - Decisive decision or feedback right: independently approve a product or issue constructive concerns that force another performer revision cycle. - Decision owner: the separate reviewer LLM conversation in ReviewDialogDualConverserGPT and review-specific subclasses; in code paths, review agents inspect executed outputs/code products separately from the generating/debugging conversation. - Supporting / enforcement mechanisms: separate ConversationManager, review termination phrase, max review rounds, product extraction/checks, code-review prompts and rewind utilities. - Closure path: performer produces valid candidate -&gt; reviewer receives the candidate/background -&gt; reviewer approves or supplies concerns -&gt; concerns are appended to the performer conversation with explicit correction request -&gt; performer rewrites/revises -&gt; review repeats. - Boundary reachability: the review dialog base class is reused by goal, planning and manuscript-writing review steps in the shipped hypothesis-testing workflow; code review is also embedded in the standard code-product path. - Why this is / is not agent-owned: the reviewer is a separate agent conversation and owns the semantic approve/challenge judgment; deterministic loop code only routes/enforces that judgment. - Claim being audited: that a current scientific product/code result is adequate/correct enough to become accepted workflow state. - Ordinary reporting path: performer response plus normal generated/executed product state. - Complementary access path: separate reviewer conversation receives the product and relevant background/output context; code review can inspect created output contents. - Independence boundary: reviewer has its own conversation manager/role and does not share the performer&#39;s assistant role; review feedback is generated independently and then returned. - Who acts on findings: the original performer/code-writing agent revises the product in the next cycle. - Evidence: dualconverser.py, requestcode.py, stepsrunner.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: use external literature/novelty evidence to develop or revise future research direction and return the selected direction into the current experimental plan, with both autonomous and Copilot parent-governed modes. - Disturbance / variety regulated: existing literature may make a candidate goal non-novel, external findings may change relevant hypotheses, and a human scientist may judge the proposed future direction inadequate. - Decisive decision or feedback right: in Autopilot, research/novelty agents judge literature-derived novelty and generate/refine the goal/hypothesis; in Copilot, human review can replace/supplement reviewer feedback and require revised research products. - Decision owner: autonomous research/reviewer agents in base mode; human scientist in the supported Copilot parent mode for the reviewed future-direction decision. - Supporting / enforcement mechanisms: literature-search agents, NoveltyAssessmentReview, ReGoalReviewGPT, stage return to GOAL, human-review application interactions, product storage and plan handoff. - Closure path: external literature -&gt; novelty/goal review -&gt; autonomous or parent judgment -&gt; if inadequate, workflow returns to goal generation/refinement -&gt; resulting goal/hypothesis/testing plan feeds data analysis and later research stages. - Boundary reachability: literature/novelty/goal refinement is part of the shipped hypothesis-testing runner, and README plus HumanReviewType/review interaction code expose Copilot human feedback through the same first-party workflow. - Why this is / is not agent-owned: the base mode closes without human direction through model-agent novelty/refinement decisions; the separately supported Copilot mode intentionally transfers the relevant review/judgment right to the human and returns that decision into workflow state. - External distinction: retrieved scientific literature and most-similar-paper evidence. - Future / prospective distinction: whether the current research goal/hypothesis is novel/appropriate enough to warrant future experimentation. - Adaptation option generated: revised research goal/hypothesis and downstream hypothesis-testing plan. - Path back into current capability / S3: failed novelty sets regoal and returns to ScientificStage.GOAL; accepted/revised goal then feeds planning, code analysis and manuscript stages. - Evidence: stepsrunner.py, dualconverser.py, README.md. - Basis: structural -\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: project parameters, research goals, human feedback and methodological guardrails constrain work, but no identity-level dispute is routed to an ultimate authority and returned as governing organizational policy. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: startup/project parameters, user research goal, coding guardrails, reviewer prompts and human-review UI. - Closure path: these controls constrain local research behavior directly; no identity/ultimate-policy issue -&gt; authoritative decision -&gt; returned policy loop is evidenced. - Why this is / is not agent-owned: neither autonomous agents nor the Copilot human are shown resolving an identity-level policy issue at this recursion. - Evidence: README.md, stepsrunner.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/data-to-paper.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"1\" data-assessment-at=\"2026-09-21T19:11:00+03:00\"><th scope=\"row\"><a href=\"https://github.com/zhayujie/CowAgent\" target=\"_blank\" rel=\"noopener\">CowAgent</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/zhayujie/CowAgent/tree/7c55a61e1bccb82c99d97a4a436f598c079f7c9d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 7c55a61e1bccb82c99d97a4a436f598c079f7c9d\">7c55a61 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously transform user/scheduled/delegated objectives into environment-facing tool/skill work and returned outcomes. - Disturbance / variety regulated: heterogeneous user objectives, model uncertainty, tool results/errors, files/shell/browser/service state, channel messages, and follow-up observations encountered during a trajectory. - Decisive decision or feedback right: choose the next reasoning/tool/skill action, incorporate returned observations, delegate bounded work when useful, or stop with a final response. - Decision owner: the running CowAgent Agent/model actor inside the first-party AgentStreamExecutor loop. - Supporting / enforcement mechanisms: ChatService, AgentBridge, provider adapters, prompt/workspace construction, tool registry, permissions, session persistence, scheduler integration and context controls. - Closure path: each tool result, delegated result or new model observation returns into the first-party executor context and can change the next autonomous action until completion. - Boundary reachability: the credited executor/bridge/tool path is the normal shipped Web/channel runtime and is instantiated directly by standard CowAgent operation at the pinned revision. - Why this is / is not agent-owned: deterministic code supplies transport, limits and execution, while the model actor owns the discretionary next-action choice on each loop iteration. - Evidence: pinned agent/chat/service.py and bridge/agentbridge.py; README.md corroborates the shipped planning/tool execution boundary. - Basis: structural and explicit. - Confidence: high. - Caveats: model/provider/tool availability, permissions and iteration limits constrain the Agent&#39;s operational discretion but do not replace its next-action judgment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate a concrete interference between sibling operational Agents when concurrent delegations target the same persistent relay conversation. - Disturbance / variety regulated: concurrent handoffs to one source→target relay session would otherwise interleave turns in the target Agent&#39;s transcript and corrupt the shared conversational state used by later delegated work. - Decisive decision or feedback right: serialize admission to that target relay session so exactly one delegated turn occupies it at a time; timeout rather than permit an overlapping handoff when the lock cannot be acquired within policy. - Decision owner: constructor-owned at the assessed boundary. The first-party S2-specific serialization primitive is complete and operational, but the conflict policy itself is deterministic/developer-selected rather than autonomously chosen by an Agent. - Supporting / enforcement mechanisms: per-relay relaylock, stable relay-session derivation, delegation roster/ACL, depth/cycle checks, timeout and synchronous result return. - Closure path: a source Agent&#39;s delegation blocks on the relay lock; after the prior target turn finishes and releases the lock, the next delegated target run executes against a non-interleaved transcript and its result returns to the waiting source Agent, changing that source&#39;s subsequent S1 behavior. - Boundary reachability: agentdelegate is a shipped team tool attached to normal team turns through AgentBridge; no downstream coordinator or test-only actor is required for the serialization path. - Why this is / is not agent-owned: Agents autonomously decide to delegate and select the teammate/task, but once two handoffs conflict the coordination choice is a fixed first-party lock policy. CowAgent therefore exposes a real S2-specific construction path without an autonomous owner of the conflict-regulation decision. - Evidence: pinned agent/tools/agentdelegate/agentdelegate.py and team-session support in bridge/agentbridge.py. - Basis: structural. - Confidence: high. - Caveats: other team features such as speaker selection, shared transcripts and ordinary handoff are not separately credited as S2 merely because they connect Agents. - Distinct S1 units: independently configured live CowAgent Agents with separate profiles/workspaces and first-party execution loops participating in one team conversation. - Inter-S1 disturbance: overlapping delegated turns to the same target relay session can interleave in the target transcript. - Attenuating coordination relation: the first-party per-relay lock queues competing handoffs and allows only one target turn at a time. - Feedback into subsequent S1 behaviour: the coordinated target result is returned synchronously to the delegating source Agent&#39;s tool loop; timeout/failure likewise returns a result that changes the source Agent&#39;s next decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the lock exists specifically because concurrent sibling handoffs would interfere by interleaving one operational transcript, and it changes admission/timing to suppress that identified disturbance before results feed back to the source Agent.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: regulate the currently configured CowAgent installation as a whole by changing which operational Agents are available, which models/capabilities they use, and which live channel instances/teams route work to them. - Disturbance / variety regulated: current mismatch between installed operational capacity and the operator&#39;s desired roster, agent availability, model/capability allocation, shared/own knowledge mode, default ownership and live channel/team bindings. - Decisive decision or feedback right: create/update/archive/delete an Agent, make an Agent default, enable/disable it, alter its model/skills/knowledge allocation, or rebind a running channel/team to a different Agent roster. - Decision owner: the authenticated self-hosted operator is the legitimate parent actor in this supported mode. - Supporting / enforcement mechanisms: AgentAdminService, roster revision checks, Web authentication, registry/router rebuilding, scheduler reconciliation, targeted live-runtime eviction and hot channel rebinding. - Closure path: the operator submits a first-party Web/API decision; CowAgent persists it, updates the live registry/router or channel binding, starts/stops the affected schedulers and evicts changed Agent instances so subsequent current work is executed under the returned control decision. - Boundary reachability: the authenticated Web console and its /api/agents administration paths are a standard shipped self-hosted operating surface documented as the unified configuration hub, not a development-only control plane. - Why this is / is not agent-owned: no standard first-party autonomous Agent is given installation-wide roster/model/capability/channel authority. The decisive current-control choice comes from the authenticated operator; runtime code only validates, persists and enforces it. - Evidence: pinned agent/admin.py, channel/web/api/agents.py, and bridge/agentbridge.py scheduler/runtime reconciliation. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: this claim is limited to installation-level current capability/resource control. Per-task steering/cancel and permission enforcement alone would not establish S3, and the assessment does not treat every settings edit as an S3 decision. - Whole-system current view: AgentAdminService.snapshot() exposes the installation&#39;s full current Agent roster, default Agent and channel instances; the same authenticated surface operates over that roster rather than one worker-local state. - Current-control decision scope: availability of S1 units, current model/capability allocation, default Agent, channel/team routing and scheduler participation for the running installation.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary and sufficiently independent audit function was established at the declared installation boundary. - Disturbance / variety regulated: none established as an S3 witness; ordinary tool feedback, run/event recording and Self-Evolution review do not provide a materially independent route to operational reality for checking production claims. - Decisive decision or feedback right: no S3-specific independent audit judgment/feedback right is supplied. - Decision owner: not established. - Supporting / enforcement mechanisms: execution/tool events, conversation/run persistence, evolution records/backups, logs and operator inspection surfaces. - Closure path: no independent audit finding→corrective-current-control loop was established; recorded events and evolution changes serve their primary execution/adaptation purposes. - Why this is / is not agent-owned: there is no qualifying audit function whose decisive judgment could be assigned to an autonomous Agent. - Evidence: pinned chat/executor event path, conversation storage, Web/admin surfaces, and agent/evolution/ review path. - Basis: structural. - Confidence: high. - Caveats: a downstream deployment could add an independent verifier or external monitor, but that composed system would be outside this frozen first-party boundary.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: convert externally observed conversation patterns and capability failures into prospective adaptations of reusable future capability. - Disturbance / variety regulated: changing user preferences and recurring work patterns, skill defects discovered in real use, reusable workflows not yet encoded as capabilities, and unfinished work whose recurrence or omission would reduce future fit. - Decisive decision or feedback right: after an idle conversation, decide autonomously whether there is a clear durable signal and whether to patch an existing skill, create a new reusable skill, consolidate knowledge/memory, or take no adaptation action. - Decision owner: the isolated first-party Self-Evolution review Agent/model actor. - Supporting / enforcement mechanisms: idle trigger thresholds, restricted evolution toolset, guarded workspace paths, pre-change backup, snapshot diff/change detection, transactional rollback and evolution records. - Closure path: the review Agent senses conversation-derived external signals, selects and writes an adaptation, the executor commits only real guarded changes, and later normal Agent runs load/use the revised skill/knowledge/persona state; if no clear signal exists it explicitly leaves capability unchanged. - Boundary reachability: Self-Evolution is started by normal AgentBridge initialization, its configuration class defaults enabled, and the standard pinned config-template.json ships selfevolutionenabled: true; the decision actor is therefore reachable in the supported distribution without borrowing a dogfood or contributor agent. - Why this is / is not agent-owned: trigger timing, backups and write guards are deterministic support, but the model review Agent owns the discretionary judgment of whether a past external interaction predicts future reusable need and which permitted adaptation to make. - Evidence: pinned agent/evolution/config.py, trigger.py, executor.py, prompts.py, bridge/agentbridge.py, config-template.json and docs/memory/self-evolution.mdx. - Basis: explicit and structural. - Confidence: high. - Caveats: simple memory consolidation alone is not the credited S4 witness. The positive mapping relies on the separately evidenced prospective skill-adaptation path: detecting a workflow likely to be wanted again or a skill defect exposed in use, autonomously generating an adaptation, and returning that change into later capability. - External distinction: the review consumes user conversation and actual skill/task experience from the environment, including repeated preferences, failures and emergent workflows. - Future / prospective distinction: the evolution prompt explicitly asks whether a workflow is reusable and likely to be wanted again, and documentation defines the goal as creating/fixing skills so they can be reused next time and future conversations improve. - Adaptation option generated: patch a defective skill, encode an emergent workflow as a new reusable skill, consolidate durable knowledge/memory, complete suitable unfinished work, or deliberately make no change. - Path back into current capability / S3: committed workspace/skill/knowledge changes are the same first-party artifacts read by subsequent normal Agent operation; operator rollback remains a separate parent intervention path rather than the owner of the autonomous adaptation judgment.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S5 / identity: - State: A(P) - Function: govern the Agent&#39;s durable identity/personality and highest-level workspace behavioral principles through first-party identity files that are loaded into subsequent system prompts. - Disturbance / variety regulated: drift between the Agent&#39;s durable identity/behavioral principles and explicit repeated signals about what the assistant should be, plus explicit operator decisions to redefine those identity/policy artifacts. - Decisive decision or feedback right: in the autonomous mode, decide whether an explicit repeated identity/personality/style signal is strong enough to justify a bounded AGENT.md identity revision; in the parent mode, authoritatively edit AGENT.md/RULE.md through the authenticated core-file administration surface. - Decision owner: base mode — the isolated Self-Evolution review Agent for the deliberately narrow autonomous identity-evolution decision; parent mode — the authenticated self-hosted operator as ultimate authority over the installation&#39;s core identity/policy files. - Supporting / enforcement mechanisms: evolution signal criteria and guarded writes/backups; AgentAdminService core-file revision checks and atomic writes; authenticated Web endpoint; prompt/workspace loader; targeted runtime eviction after operator edits. - Closure path: autonomous mode: repeated identity-level external signal → review-Agent identity judgment → guarded AGENT.md edit → subsequent runtime loads the changed persona. Parent mode: authenticated operator reads/edits a core identity/policy file → atomic persistence and cached-Agent eviction → subsequent Agent instance reloads that file into its system prompt. - Boundary reachability: both modes are shipped supported runtime paths: default-enabled Self-Evolution may edit AGENT.md under its standard guard, while the authenticated Web Agents API exposes core-file read/write and immediately evicts the changed runtime. - Why this is / is not agent-owned: the base identity change is not a static prompt or automatic parser; the review Agent must judge whether a rare explicit repeated signal warrants changing its own identity artifact. The separate operator mode retains parent authority to set or override the same identity/policy surface, hence A(P) rather than plain A. - Evidence: pinned agent/evolution/prompts.py, executor.py, agent/prompt/workspace.py, agent/prompt/builder.py, agent/admin.py and channel/web/api/agents.py. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: ordinary permission settings, tool approvals, memory/preferences and per-task steering are not credited as S5. The autonomous claim is narrowly limited to the explicit first-party AGENT.md identity-evolution path; operator edits establish the separate parent mode. - Identity / ultimate-policy issue: AGENT.md is explicitly defined by the shipped templates as the Agent&#39;s identity/personality and is loaded with RULE.md into the system-prompt context; this is materially different from ordinary task or tool policy. - Ultimate authority in each claimed mode: base (A) — Self-Evolution Agent decides whether the standard rare-signal criterion warrants a durable identity edit; parent (P) — authenticated operator directly owns the authoritative core-file edit and may override/undo Agent evolution. - Return-to-operation path: both modes persist the core file used by prompt construction; operator writes additionally evict the cached runtime, and later Agent initialization reloads the changed identity/policy context.\">A(P)</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a00011ae5e8e9ee62aa713d51f283559f12102d4/assessments/cowagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a00011ae5e8e9ee62aa713d51f283559f12102d4\">a00011a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/agno-agi/agno\" target=\"_blank\" rel=\"noopener\">Agno</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/agno-agi/agno/tree/44219f8532e2fe6ce936850455f4b9a2567e4194\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 44219f8532e2fe6ce936850455f4b9a2567e4194\">44219f8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: member agents autonomously execute bounded model/tool work and return results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: TeamMode.tasks provides an out-of-box agent-owned mutual-adjustment loop over a shared task board. The leader assigns ownership, prevents duplicate tasks, encodes dependencies, observes member outcomes and can retry/reassign/change the plan; dependency state prevents conflicting/premature execution. This goes beyond one-shot delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the same leader has a current whole-team view of tasks, assignees, dependency/blocked state, results and failures, plus authority to create/reprioritize through dependencies, assign/reassign members, execute work, update status and decide overall completion. That is a concrete agent-owned current-control loop over shared operational commitments. Human-in-the-loop paths pause member/tool execution and return the result to the team; they do not independently take ownership of the team-level assignment/plan/completion right, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: Agno lets applications compose reviewer/critic members, but the standard team runtime does not supply a distinct sufficiently independent audit channel with alternative operational access and required corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, knowledge, reasoning and learning capabilities can improve team operation but do not by themselves instantiate a distinct external-and-prospective intelligence function coupled against S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: team role, instructions, permissions, approvals and identity are application/parent configured. The tasks leader regulates execution but is not given ultimate agent-owned policy/identity authority or an S3–S4 closure role.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/agno.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-31T23:02:10+03:00\"><th scope=\"row\"><a href=\"https://github.com/sgeos/pydromon\" target=\"_blank\" rel=\"noopener\">pydromon</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-31\">2026-10-31</time></td><td class=\"review-ref\"><a href=\"https://github.com/sgeos/pydromon/tree/65671672b812b1d4c88f8e7633fdd3a1e50bb5f0\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 65671672b812b1d4c88f8e7633fdd3a1e50bb5f0\">6567167 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Configured session lines produce project work and exchange results through their first-party daemon composition. - Disturbance / variety regulated: User tasks, local workspace changes, messages, background runs and engine/tool failures. - Decisive decision or feedback right: Choose local tools, communications, work actions and whether to continue or end a turn. - Decision owner: The model-backed session-line actor; external Claude/Codex/Pi engines supply inference/tool-loop dependencies rather than autonomous Dromon metasystem judgments. - Supporting / enforcement mechanisms: First-party driver construction, tool exposure, mailbox/event log, wake scheduler, sandbox/settings composition and persisted engine sessions. - Closure path: Queued mail/wake → line prompt and configured engine → chosen tools/messages/work → recorded turn outcomes → later line turns. - Boundary reachability: The distributed daemon creates configured session lines with first-party Dromon tools and driver/engine wiring. The supported Claude/Codex-backed composition is executable without implementing a new harness. - Why this is / is not agent-owned: Without the model-backed line actors, the daemon transports messages and enforces policy but cannot choose meaningful project work. Dromon does not receive credit for unrelated engine features. - Evidence: [Scheduler][R1], [engine composition][R2], [daemon][R3], [line configuration][R4], [README][R5]. - Basis: structural. - Confidence: high. - Caveats: No live subscribed engine or paid model was run; engine independence and operational quality are not claimed.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Declared resource leases and role-seat ownership regulate concrete shared-resource/write collisions among operational lines. - Disturbance / variety regulated: Two active lines may try to use the same named project resource; role seats sharing a worktree must avoid competing writers and stale ownership transitions. - Decisive decision or feedback right: A line chooses when to acquire/release a resource lease and can hand off or recover role ownership subject to observed eligibility. - Decision owner: Configured agent lines own invocation/release/handoff choices; the operator declares permitted resource names/role terms, and deterministic state validates exclusivity. - Supporting / enforcement mechanisms: Lease holder/expiry events, refusal with holder/expiration feedback, non-renewal/TTL, role owner invariants, engine access rebuilding and journaled handoff. - Closure path: Contender calls acquire → receives grant or current-holder/expiry refusal → adjusts later resource use; release/expiry enables another acquisition. Role handoff records a note, transfers authority, wakes the successor and rebuilds the former owner&#39;s access. - Boundary reachability: acquirelease/releaselease and seat ownership tools are supplied to running lines by Scheduler; project-config leases/roles enable the shipped path, not a custom conflict resolver. - Why this is / is not agent-owned: The actors decide when to reserve/release/pass work; the log and guards enforce those decisions. This credits that bounded agent-mediated coordination mode, not generic messaging or the scheduler itself. - Evidence: [Lease tool and role tool implementations][R1], [role invariants/one-writer boundary][R6], [project enablement][R7], [line tool semantics][R4]. - Basis: structural. - Confidence: medium. - Caveats: Resource leases are cooperative: unmanaged external processes or ignored lease conventions are not forcibly excluded. Deterministic automatic failover is support, not autonomous discretion.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: The project operator regulates the whole current set of session lines, role capacity, budgets and continuing commitments. - Disturbance / variety regulated: Runaway autonomous turns/cost, held or failed lines, exhausted provider plans, conflicting current staffing and engine availability. - Decisive decision or feedback right: Review project-wide state and choose line/role/budget/hibernation/rebind/interruption/release changes or answer a held line. - Decision owner: The authenticated local project operator, acting as the legitimate parent of the project run. No first-party autonomous whole-project controller is established. - Supporting / enforcement mechanisms: Private operator socket, all-line status summaries, durable events, operator-attributed messages, hold notices/question queue, CLI commands and scheduler/engine enforcement. - Closure path: Whole-project status or held-line notice → operator current-control choice → daemon command/event → scheduler applies limits, ownership, model, hold or interruption changes → subsequent turns run under the returned decision. - Boundary reachability: Daemon.execute serves operator-authority status/settings/role/budget/configure/release/interrupt commands, and status includes every line. The first-party scheduler routes hold questions and operator answers back into later operation. - Why this is / is not agent-owned: Removing the operator leaves fixed limits and failover machinery, not discretionary whole-system resource/commitment revision. P describes the supplied supervised mode; enforcement does not become A or C. - Evidence: [Operator protocol dispatch/current status][R3], [holds and operator-answer scheduler][R1], [project limits/roles][R7], [role runtime updates][R6], [client protocol][R8]. - Basis: structural. - Confidence: high. - Caveats: The parent boundary is this local project, not the public OSS organization; operator socket access is an explicit trust assumption.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No installed complementary independent audit judgment-and-corrective-return loop is supplied. - Disturbance / variety regulated: Incorrect work-completion claims, stale notes, disclosure mistakes and engine-reporting errors. - Decisive decision or feedback right: No separate audit-specific actor or constructor adjudicates operational truth and returns corrective control. - Decision owner: Lines report their work; runtime observes process/session/log facts. Read-only seats are configured by users without a supplied audit workflow. - Supporting / enforcement mechanisms: Daemon-stamped commit hashes, role journals, activity/event logs, raw transport evidence/replay and disclosure checks. - Closure path: Facts can be inspected by an operator or peer; the standard product has no audit verdict/corrective-action protocol for a particular completion claim. - Why this is / is not agent-owned: Independent fact capture is useful evidence but is not itself discretionary complementary audit; tests, developer reviews and optional advisory seats do not supply an installed audit function. - Evidence: [Scheduler status/journal/check tools][R1], [engine transport evidence][R2], [evidence store][R9], [role design][R6], [line tools][R4]. - Basis: structural. - Confidence: high. - Caveats: A user can organize reviewer lines through general messages; that application would need separate function/independence/closure evidence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No external-and-prospective adaptation loop is supplied. - Disturbance / variety regulated: Provider budget changes, new model choices and suggested project patches are available current inputs. - Decisive decision or feedback right: No shipped intelligence actor develops future-oriented capability options and closes their return into current capability. - Decision owner: Operator chooses reconfiguration/upgrades; ordinary lines may submit untrusted patch proposals. - Supporting / enforcement mechanisms: proposechange storage, project reload/rebind, provider-budget failover and optional local teacher lifecycle. - Closure path: Proposals are explicitly never applied by Dromon; teacher code only loads/unloads a local model. Rebinding/failover responds to present availability rather than prospective adaptation. - Why this is / is not agent-owned: A future roadmap, a model called teacher, context handoff or a current capacity switch is not S4. Generic operator patch handling does not create a function-specific parent adaptation loop. - Evidence: [Proposal no-apply contract][R10], [teacher boundary][R11], [role failover][R6], [reload/rebind][R3]. - Basis: structural. - Confidence: high. - Caveats: Repository-development/dogfood decisions and future Rust/Keleusma ports are adjacent.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No function-specific identity/ultimate-policy decision-return loop is supplied. - Disturbance / variety regulated: Access/disclosure rules, operator messages, project instructions and role terms. - Decisive decision or feedback right: No identity-level issue is specifically adjudicated and returned by ultimate authority as a new governing policy. - Decision owner: Operator configures the project and its permission/disclosure boundaries; agents have explicitly bounded local tools. - Supporting / enforcement mechanisms: Operator/line address attribution, private socket trust, disclosure checks, tool/recipient policies, protected state and role rules. - Closure path: Configuration and operator answers alter current execution, but no identity/ultimate-policy issue/decision protocol or S3–S4 balance closure is supplied. - Why this is / is not agent-owned: The operator is a real parent for S3 current control; that does not promote all configuration or question replies to S5. - Evidence: [Operator and line authority split][R3], [line tools/policy][R4], [project configuration][R7], [scheduler trust and question semantics][R1]. - Basis: structural. - Confidence: high. - Caveats: First-party development documents record human design decisions, but those are not an installed policy actor in an arbitrary user project.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b8dbf77260552d46200e82343dce1fc8cd20a3db/assessments/py/pydromon.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b8dbf77260552d46200e82343dce1fc8cd20a3db\">b8dbf77 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-01T00:17:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/quqxui/RSI-Flow\" target=\"_blank\" rel=\"noopener\">RSI-Flow</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-31\">2026-10-31</time></td><td class=\"review-ref\"><a href=\"https://github.com/quqxui/RSI-Flow/tree/0f87c2b198f22e5697853cfc6d0bf2d002e48ca7\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0f87c2b198f22e5697853cfc6d0bf2d002e48ca7\">0f87c2b &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: A configured Pi/DeepSeek agent performs the substantive target task inside a first-party versioned workflow session. - Disturbance / variety regulated: Task instructions, tool/workspace state, model observations and failed subtasks under an operator-defined experiment. - Decisive decision or feedback right: The model chooses its response/action within an exposed task turn; results and tool feedback inform subsequent turns where the selected SDK supports them. - Decision owner: The model-backed target agent operating through the native driver; the engine and experiment runner do not choose its per-task response. - Supporting / enforcement mechanisms: Native SDK bridge, workspace/runtime snapshots, bounded prompt interface, execution timeout, credentials, receipts and result parsing. - Closure path: Input task and versioned target artifact → native model-backed agent turn → task/tool result → next agent turn and final response/experiment feedback. - Boundary reachability: Native integration is shipped under integrations/native/, wired to Pi/DeepSeek adapters and documented as supported task execution, rather than only a test mock. - Why this is / is not agent-owned: The model decides task behavior; removing the native model leaves an experiment runner capable of testing artifacts, not autonomous task judgment. - Evidence: native worker, Pi driver, DeepSeek driver, README. - Basis: structural. - Confidence: medium. - Caveats: Task-level S1 depends on the configured native agent/provider; built-in offline demonstration is not proof of model autonomy or real-provider success.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No first-party anti-interference coordination among distinct task-performing S1 cells is established. - Disturbance / variety regulated: Concurrent candidate trials could contend for resources or contaminate comparisons. - Decisive decision or feedback right: The framework bounds parallel work and separates trial artifacts; no inter-S1 conflict-specific adjustment is evidenced. - Decision owner: Preselected execution protocol and deterministic trial harness rather than an autonomous coordinator. - Supporting / enforcement mechanisms: Task batching, trial directories, stable task IDs, budget reservations and timeouts. - Closure path: Runner results are gathered into comparison; no disturbance-detecting cross-agent coordination decision returns to alter their working relationships. - Why this is / is not agent-owned: Isolation and scheduling protect tests but are not the S2-specific regulation of interactions between ongoing autonomous S1 units. - Evidence: validation stage, budget ledger, native runner. - Basis: structural. - Confidence: medium. - Caveats: Different target frameworks may implement their own coordination; those internals are outside this review.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No agent-owned or specifically parent-governed whole-system discretionary control of concurrent current S1 priorities and commitments is established. - Disturbance / variety regulated: Budget exhaustion, failed trials, protocol violations, incomplete receipts and target-version conflict. - Decisive decision or feedback right: Acceptance thresholds and stop/rollback predicates are fixed by operator-selected protocol; these do not choose new organizational priorities in a current whole-system view. - Decision owner: Human configuration supplies constraints, deterministic engine enforces them; no in-run S3 discretion is identified. - Supporting / enforcement mechanisms: BudgetLedger, SingleRoundSearch, decide, deploy, pause/resume/cancel/recover and process isolation. - Closure path: Status and budget checks deterministically stop, reject or deploy a version; the engine does not revise commitments among distinct ongoing S1 operations. - Why this is / is not agent-owned: An operational gate and rollback authority do not become managerial judgment merely because they have effect on execution. - Evidence: engine, selection, adapters. - Basis: structural. - Confidence: medium. - Caveats: A custom SearchPolicy may implement additional control but no such standard autonomous whole-system owner is wired.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independent complementary audit of S1 claims with an audit-owned corrective return is established. - Disturbance / variety regulated: False task success, inaccurate version-loaded claims and unverifiable experiments. - Decisive decision or feedback right: Evaluator, outcome receipts and load verifier check protocol predicates but do not exercise separate complementary organizational audit judgment. - Decision owner: The same experiment engine owns ordinary comparison/admission; no independently authorized auditor is composed. - Supporting / enforcement mechanisms: Paired evaluation, task receipts, exact-version digest, load verification, report evidence and regression thresholds. - Closure path: Comparison flows into ordinary Stage 6 acceptance; failed load checks trigger procedural rollback, not an independent audit finding sent to a corrective S3 owner. - Why this is / is not agent-owned: Test comparison and defensive proof of load are valuable controls, but routine QA is not necessarily an independent complementary S3 challenge. - Evidence: validation, selection, reports. - Basis: structural. - Confidence: medium. - Caveats: An operator can independently inspect raw receipts, but that is not an evidenced first-party audit-return mode.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: A configured reasoning agent generates prospective changes to the target agent&#39;s prompt/workflow from accumulated experience and diagnosed limitations. - Disturbance / variety regulated: Recurring task failures, observed regressions, changes in future task mix and limits of the deployed artifact. - Decisive decision or feedback right: Choose candidate artifact changes, hypothesis and expected benefit, or explicitly propose no change; a subsequent protocol governs acceptance. - Decision owner: The configured model-backed CommandProposer (including the Codex integration) chooses a future adaptation option; the human-proposal mode separately supplies offline input but does not erase the supported autonomous path. - Supporting / enforcement mechanisms: Structured diagnosis, proposal context, key allowlist, versioned artifact build, baseline/candidate comparison, decide and verified deploy. - Closure path: Historical experience → diagnosis → reasoning backend chooses prospective artifact modifications → constrained build and paired evaluation → accepted new deployed artifact changes later target-agent sessions. - Boundary reachability: Engine.proposer selects command reasoning from config and Stage 4 invokes proposer.propose; the returned candidate flows into supported Stage 5 and Stage 6 deployment, not merely into documentation. - External distinction: Imported version-labelled task outcomes and feedback characterize target performance beyond the current agent turn. - Future / prospective distinction: Proposed prompt/workflow modifications concern future agent capability rather than a response to a present task. - Adaptation option generated: A structured candidate with hypothesis, expectedbenefit and allowed artifact changes, or nochange. - Path back into current capability / S3: The accepted content-addressed version is loaded/verified for subsequent task runs, with rollback after unsuccessful deployment. - Why this is / is not agent-owned: The model chooses the substantive candidate hypothesis and changes; deterministic gates can reject it but do not invent the adaptation option. - Evidence: proposal reasoning, engine proposer wiring, improvement, deployment. - Basis: structural. - Confidence: medium. - Caveats: Autonomous adaptation requires configured reasoning backend and provider; a candidate is not deployed without human-selected test thresholds and successful tests. Source evidence is not a live improvement-outcome claim.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party identity/ultimate-policy dispute resolution and binding return for the RSI installation is established. - Disturbance / variety regulated: What targets, prompts, models, budgets and artifact fields should be legitimately allowed to change. - Decisive decision or feedback right: Human operator fixes target schema, allowed keys, model configuration and evaluation rules at initialization; no identity-policy issue is referred to an adjudicator for resolution. - Decision owner: Operator/developer outside the live run; model proposer is restricted to editable lower-level artifact fields. - Supporting / enforcement mechanisms: Immutable config hash, key allowlist, model identity snapshots, validation errors and manual stop. - Closure path: Fixed policy blocks out-of-bounds proposals; it does not carry an identity question to a legitimate policy owner and feed a fresh ruling back into operations. - Why this is / is not agent-owned: Artifact edits and accepted versions adjust capability, not ultimate purpose/constitutional identity; immutable settings are enforcement not adjudication. - Evidence: definition, improvement, engine. - Basis: structural. - Confidence: high. - Caveats: A developer may deliberately install new policies in a new workspace, but that is not a first-party governed S5 mode.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/35a76015978b6753215beac6e12cb62e542ba822/assessments/rs/rsi-flow.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 35a76015978b6753215beac6e12cb62e542ba822\">35a7601 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-28T19:32:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/kumizeod/AgentForeman\" target=\"_blank\" rel=\"noopener\">AgentForeman</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-28\">2026-10-28</time></td><td class=\"review-ref\"><a href=\"https://github.com/kumizeod/AgentForeman/tree/634f9c0906f133fc577d6291c29b8f8cfd6af02a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 634f9c0906f133fc577d6291c29b8f8cfd6af02a\">634f9c0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: produce candidate code/experiments and general task artifacts through model decisions with returned evidence. - Disturbance / variety regulated: heterogeneous goals, failed code/training, poor candidates and contradictory evidence. - Decisive decision or feedback right: choose experiment/repair/retest/stop and instructions; author source or artifacts; revise after independent criticism. - Decision owner: configured model-backed manager, coding worker, contributors and integrator, invoked by first-party protocols. - Supporting / enforcement mechanisms: source snapshots, typed responses, worker pool leases, edit allowlist, native training/checks, archives and round/deadline bounds. - Closure path: verified baseline → manager model choice → worker action → independent measurement/criticism → next choice or revision → preserved terminal result. - Why this is / is not agent-owned: removing the model roles leaves deterministic transport and checks but no substantive hypothesis, edit or report decision. - Caveats: A is structural ownership, not proof of live model quality; external coding tools are credited only as explicitly assembled task actors. - Boundary reachability: CLI campaign/overnight and cooperate/debate commands assemble these roles and execute their chosen actions; they are shipped supported modes, not test-only prompts. - Evidence: src/agentforeman/manager.py; src/agentforeman/campaign.py; src/agentforeman/engine.py; src/agentforeman/cooperate.py; src/agentforeman/debate.py; src/agentforeman/poolworker.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no separately closed inter-S1 interference regulation at the declared task boundary. - Disturbance / variety regulated: independent contributions can be inconsistent; worker contention and duplicate execution are mechanically bounded. - Decisive decision or feedback right: integrator chooses combined output, but contributors are not subsequently coordinated through a specific inter-unit correction loop. - Decision owner: integrator owns S1 synthesis; runtime owns fixed sequencing/leases, with no separately evidenced autonomous S2 discretion. - Supporting / enforcement mechanisms: independent assignments, integration contract, queue/lease locks, quota cooldown and critique of combined artifacts. - Closure path: contributors return once → integrator revises the combined product; duplicate jobs are suppressed by fixed IDs/locks. - Why this is / is not agent-owned: decomposition, waiting for all contributions and rewriting one combined answer do not establish mutual adjustment of operational units. - Caveats: does not deny coordination in a broader organization assembled around this tool. - Evidence: src/agentforeman/cooperate.py; src/agentforeman/pool.py; docs/COOPERATIVE.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no whole-system discretionary current-control function over a portfolio established at this boundary. - Disturbance / variety regulated: candidate failure, incumbent comparison, quota waits and bounded task duration. - Decisive decision or feedback right: manager chooses the next experiment within one fixed objective; it cannot change resources, task goal or budgets. - Decision owner: model owns local S1 research choices; operator/configuration selects task scope, role pool and limits; runtime enforces those choices. - Supporting / enforcement mechanisms: campaign rounds/best record, budget/deadline checks, role registry, UI status, cancel and resume. - Closure path: measured rounds return to a next-task-action choice; generic stop/confirmation returns no evidenced whole-system resource bargain. - Why this is / is not agent-owned: the campaign manager name does not turn its local experimental policy into a metasystem; fixed quotas are enforcement. - Caveats: broader multi-project allocation may be performed externally but is outside the declared first-party campaign mode. - Evidence: src/agentforeman/manager.py; src/agentforeman/campaign.py; src/agentforeman/briefing.py; src/agentforeman/pool.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: challenge operational claims through separate model audit/critique with complementary original evidence and corrective return. - Disturbance / variety regulated: unsupported synthesis claims, missed criticism, inadequate experiment plans and false candidate success. - Decisive decision or feedback right: distinct critic/auditor chooses anchored findings and accept/revise/reject; campaign reviewer can block or return an executable proposal for revision. - Decision owner: separately invoked model reviewer/auditor roles; deterministic gates apply verdict consistency and run trusted checks. - Supporting / enforcement mechanisms: distinct role identities, read-only review snapshot, source/check/artifact anchors, issue ledger, frozen verifier and bounded revision/retest. - Closure path: raw artifacts/source/check receipts → separate critic judgment → integrator/manager revision and recheck, or stopped/needs-evidence/rejected result; council audit conditions final disposition. - Why this is / is not agent-owned: model audit judgment owns substantive criticism; deterministic parsing and trusted checkpoint measurement are support, not the owner of that judgment. - Caveats: distinct identities are not statistically independent models; supplied sources are not authenticated by quote matching, and live factual correctness remains unmeasured. - Boundary reachability: documented campaign --review, cooperative distinct-reviewer mode and council audit are shipped runtime modes; no developer fixture is needed to select them. - Claim being audited: candidate/proposal or chair/integrator output is supported by original source material, controls, actual artifacts and check results. - Ordinary reporting path: manager rationale, proposer artifacts and chair/integrator summary. - Complementary access path: reviewer receives copied source snapshots plus experiment evidence; general critics receive full artifact/source/check anchor documents, and council auditor sees original answers and all criticism rather than chair summary alone. - Independence boundary: separate read-only sessions/role identities from author/integrator/chair; no authorship permission for the reviewer. Trusted verifier directly reads tensors without importing candidate code, adding corroboration rather than autonomous judgment. - Who acts on findings: campaign manager/integrator revises under recorded issue IDs; controller blocks/returns or marks needsevidence/rejected instead of fabricating success. - Evidence: src/agentforeman/discussion.py; src/agentforeman/campaign.py; src/agentforeman/debate.py; src/agentforeman/council.py; src/agentforeman/templates/moons/verify.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no external-and-prospective adaptation loop changing AgentForeman operational capability. - Disturbance / variety regulated: new research hypotheses, failed experiment results, provider quota changes and user task uncertainty. - Decisive decision or feedback right: manager may change candidate experiment code, not harness capability/organization; task chair clarifies current requirements. - Decision owner: task agents own research outcomes; maintainer/operator owns external product evolution. - Supporting / enforcement mechanisms: research plans, measurements, council sources, quota information and roadmap. - Closure path: research findings return to the current task; no prospective environmental judgment returns as a change to harness capability. - Why this is / is not agent-owned: research as the primary operational transformation is S1; internal optimization and quota reaction do not establish S4. - Caveats: an operator could use outputs to redesign its organization, but that external act is not a shipped adaptation closure. - Evidence: src/agentforeman/manager.py; src/agentforeman/campaign.py; src/agentforeman/council.py; src/agentforeman/briefing.py; docs/ROADMAP.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy adjudication loop established beyond bounded task contracts. - Disturbance / variety regulated: unclear scope, changed deliverables/acceptance/autonomy and stale user confirmation. - Decisive decision or feedback right: human confirms a task contract; agents must pause when they report a scope change, rather than decide ultimate policy. - Decision owner: operator owns the local task mandate; product identity remains maintainer-defined outside runtime. - Supporting / enforcement mechanisms: version/fingerprint confirmation, allowed-decision/pause fields, frozen checks, scope-change signal and stop controls. - Closure path: briefing → exact human confirmation → bound child task; requested scope changes pause for new clarification. - Why this is / is not agent-owned: this is operational task admission and authority bounding; it is not an identity/ultimate-policy dispute between present operations and future adaptation. - Caveats: contract editing is a real returned human decision but does not by itself satisfy the function-first S5 threshold. - Evidence: src/agentforeman/briefing.py; src/agentforeman/taskcontract.py; src/agentforeman/debate.py; docs/BRIEFING.md. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/8100f851f4f20a52d8b11424bbccf95b1d296801/assessments/ag/agentforeman.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 8100f851f4f20a52d8b11424bbccf95b1d296801\">8100f85 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-10-24T20:13:26+03:00\"><th scope=\"row\"><a href=\"https://github.com/3ae3ae/harness2-cli\" target=\"_blank\" rel=\"noopener\">Harness² CLI</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-24\">2026-10-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/3ae3ae/harness2-cli/tree/0c811344a4edfe34960b2fc8f286369d7e81fb27\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0c811344a4edfe34960b2fc8f286369d7e81fb27\">0c81134 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Bounded model-backed improvement work per encountered task: examine operational evidence, edit a harness, probe the edited candidate and produce a selected task harness plus result. - Disturbance / variety regulated: Different user problems and actual coding-agent failures demand different instruction, skill, script or hook changes; candidate edits can also violate a harness component contract. - Decisive decision or feedback right: Configured improver chooses candidate file changes and explains them against evidence. The model selector (in automatic mode) chooses a final task result where multiple candidates exist. - Decision owner: Model-backed proposer/editor and optional automatic selector, invoked through the first-party session interface. External executor cognition is a dependency, but the improvement goal and agent-edit control path are shipped by the reviewed CLI. - Supporting / enforcement mechanisms: Workspace harvest, component allowlist, tree validation, per-stage retry/fallback, rollout adapter, result/trajectory records and candidate selection parser. - Closure path: Current base-task rollout → independent agent-edited harness trees → validated candidate task probes → composed candidate and selector result → accepted task-harness and evidence for later reuse. - Boundary reachability: cli.run constructs Proposer with the installed channel config and invokes schedule.runsweep; runtask calls recursion.runmode, whose runstage actually invokes Proposer.call with writable context/harness and captures its changed tree, then probes candidates. All are included in the shipped CLI mode. - Why this is / is not agent-owned: The model makes contentful harness edits and, when configured, evidence-driven task-result choices; source-local Python merely bounds and enforces those decisions. Dry-run, static tests and deterministic fixtures by themselves do not prove model autonomy. - Evidence: run.py, recursion.py, proposer.py, schedule.py. - Basis: Supported live-model session path at the frozen commit, not asserted empirical success rate. - Confidence: High for source-wired decision ownership; outcome quality untested. - Caveats: The target coding assistant and provider are externally configured and not extra first-party viable S1 units.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No evidenced S2-specific stabilization among two distinct, separately viable owned S1 units. - Disturbance / variety regulated: Concurrent candidate and domain execution might consume resources, but distinct S1 divisions and an inter-unit oscillation/collision control relation are not established. - Decisive decision or feedback right: Deterministic concurrency width, domain ordering, semaphore and run-label isolation coordinate experimental steps, not an agentic inter-S1 conflict response. - Decision owner: Static Python scheduler and operator configuration. - Supporting / enforcement mechanisms: ThreadPoolExecutor, proposer semaphore, namespace isolation, mode/domain libraries and run budget. - Closure path: Scheduled experiments complete and aggregate; no S2-specific sensed interference and returned reciprocal adjustment across autonomous operating units. - Why this is / is not agent-owned: Stage-level parallelism, composition and result pooling are parts of one bounded optimization process, not S2 because they run concurrently. - Evidence: schedule.py, recursion.py, proposer.py. - Basis: Scoped source negative after examining task and domain concurrency. - Confidence: High. - Caveats: An external multi-agent product using this CLI might provide S2 independently.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-current control relationship over independently viable operational divisions at this recursion. - Disturbance / variety regulated: Budget overruns, candidate failures, task completion, user approval and project file drift are local run/deployment constraints rather than multi-unit resource/commitment governance. - Decisive decision or feedback right: The operator sets execution budget, task set and allowed surface; runtime enforces limits; selectors compare results. None revises current commitments across distinct S1 units with systemic authority. - Decision owner: CLI user for configuration, deterministic scheduler for enforcement and model for candidate choice; no separately supported S3 owner. - Supporting / enforcement mechanisms: Budget/call caps, run status, concurrency limit, retries, apply conflict checks and --force option. - Closure path: Fixed run settings → bounded task experimentation → output; absent whole-current S3 view, discretionary priority/resource intervention and returned binding adjustment to multiple ongoing units. - Why this is / is not agent-owned: Picking a better harness is an operational or prospective adaptation choice; enforcing an operator&#39;s preset budget is not agent-owned S3 and ordinary apply approval is not parent-governed whole-system control. - Evidence: run.py, schedule.py, apply.py. - Basis: Bounded negative of whole-organization current-control closure. - Confidence: Medium-high. - Caveats: Operator may manage a larger organization, but its current control is not implemented by this application.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independently complementary audit channel challenges routine S1–S3 reports and closes findings into corrective systemic control. - Disturbance / variety regulated: Bad candidate harness files, inaccurate agent result claims and poor task answers are checked by local tree validation, rollout comparisons, benchmark judging or optional evaluation. - Decisive decision or feedback right: Ordinary candidate validators, task selector and eval compare outputs; none has separately independent authority to audit a standing S3 report and route corrective findings to management. - Decision owner: Deterministic validators/evaluation routines, configured model selector or human comparator within the same adaptation process. - Supporting / enforcement mechanisms: Harness component checks, anonymous candidate selection, result reports and user-triggered eval. - Closure path: Candidate/result evidence → within-loop selection and optional later quality measurement; no complementary audit → binding whole-current corrective return. - Why this is / is not agent-owned: Independent improver proposals and blind selection reduce some bias, but are routine production/evaluation, not an independent S3 oversight path. - Evidence: selection.py, eval.py, judge.py. - Basis: Scoped negative distinguishing quality checks from complementary audit independence. - Confidence: Medium-high. - Caveats: A separate external QA team could supply such audit for a deployed agent but is outside this reviewed system.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: Model-backed across-task prospective harness adaptation with a second, explicitly supported parent-controlled blind-selection mode that changes which candidate and lesson enter the future task library. - Disturbance / variety regulated: Unfamiliar project tasks, newly observed errors and weak transfer of task-specific improvements to later tasks; user may also disagree with automated candidate choice. - Decisive decision or feedback right: Automatic selector chooses the adopted candidate and reflector extracts a transferable lesson; in --selector human mode the user personally selects among blinded final candidates while a model reflector can distill the adopted result. The choice feeds subsequent tasks through the library. - Decision owner: A: model-backed selector and reflector/proposer in CLI sweep; P: operator at the shipped interactive selector, not the benchmark author or external research institute. Each mode has separately attributable adoption authority. - Supporting / enforcement mechanisms: Per-domain sequential Library, selectionpool, anonymous candidate files, human TTY prompt/choice, adopted tree and experience persistence, context.build injection into later proposer contexts; final project deployment is optional with apply. - Closure path: Encounters and candidate execution evidence → automatic/human chosen task harness → model-reflected generalizable lesson → modelib.add → next task&#39;s proposal context includes earlier domain library → potential changed subsequent harness. After a run, generated consolidated harness may also be explicitly applied to project files. - Boundary reachability: Shipped cli/run.py chooses HumanSelector when selector.channel.kind == human; otherwise it instantiates model-backed Proposer. Both invoke schedule.runsweep and selection.runselection; schedule.runonemode calls reflectadoption and conditionally modelib.add, while next task&#39;s runstage loads the library. cli/apply.py separately permits reviewed real project-file adoption. - External distinction: Actual newly encountered user task domains and contrasted coding-agent trajectories expose operational shortcomings not specified in a fixed harness. - Future / prospective distinction: Per-domain transferable lessons plus consolidated project harness target future tasks, rather than merely grading or repairing one immediate deliverable. - Adaptation option generated: Model editor proposes changed skills/instructions/scripts/hooks; model/human selector adopts a tested candidate; reflector writes future-reuse cues; consolidation proposes project-wide next-task harness. - Path back into current capability / S3: Selected experience is persisted in the per-domain library and read by subsequent model proposer sessions, changing the options considered for later edits. The optional apply command installs consolidated or one-task adopted components into the user&#39;s project; no independent S3 manager is asserted. - Why this is / is not agent-owned: A has agent-owned candidate choice and lesson generation with model decisions returning through first-party memory to later operations. The distinct P mode assigns the same consequential selection right to the user through a real terminal interaction and returns it through the same library. This does not assign the separately guarded final installation to the model. - Evidence: run.py, human.py, selection.py, schedule.py, library.py, apply.py. - Basis: The two first-party shipped prospective adaptation loops share the persistent future-facing library, but have distinct actual adoption decision owners. - Confidence: High for reachable branch/closure, medium for model generalization since no model runs were made. - Caveats: --selector human requires a TTY and multiple finalists (k &gt; 1); at k=1 selection is trivial. A failed reflection yields no transferable lesson. Project apply defaults to human approval and is not evidence of autonomous project deployment.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No legitimate ultimate identity/mission-policy adjudication is shipped for the overall improvement organization. - Disturbance / variety regulated: Operator task selection, allowed editable files, model/provider choice, benchmark scope and safety limits bound execution but do not create a separate ultimate policy decision loop. - Decisive decision or feedback right: User chooses and configures the run and can approve/force project-file writes; no identity-level conflict is escalated to a legitimate authority and returned as governing policy. - Decision owner: External developer/project owner for the overall purpose; shipped runtime for validation and configured model for bounded edits. - Supporting / enforcement mechanisms: CLI config and setup, component tree validator, source boundaries, apply confirmation and git-dirty checks. - Closure path: User-provided goal and constraints → local optimization and optional installation; absent system identity dispute → authority judgment → returned revised governing policy. - Why this is / is not agent-owned: Supervised application is an operational/capability adoption gate, not by itself an identity- or ethos-level S5 decision. The parent-mode S4 classification does not automatically imply S5=P. - Evidence: settings.py, run.py, apply.py. - Basis: Bounded negative for identity-level authority and operational return. - Confidence: Medium-high. - Caveats: The user&#39;s broader software organization may have S5; this repository does not establish its governance authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b4570aa846bcb5c7e3c02ccabec88b26877d4335/assessments/ha/harness-cli.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b4570aa846bcb5c7e3c02ccabec88b26877d4335\">b4570aa &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-10-26T18:56:20+03:00\"><th scope=\"row\"><a href=\"https://github.com/amosblomqvist/learnharness\" target=\"_blank\" rel=\"noopener\">LearnHarness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-26\">2026-10-26</time></td><td class=\"review-ref\"><a href=\"https://github.com/amosblomqvist/learnharness/tree/3dc88472eea41eed0d5e5f29c2f16f8d063c415b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3dc88472eea41eed0d5e5f29c2f16f8d063c415b\">3dc8847 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Perform goal-directed teaching, research, demonstration construction and visual/PDF assistance under a chosen lesson mission. - Disturbance / variety regulated: Uncertain starting competence, unexpected wrong answers, unfamiliar facts, tool failures and domain-specific problems requiring outside evidence or visualization. - Decisive decision or feedback right: Active prober/teacher models choose questions, explanation revisions, quiz checks, graph lookup and specialist delegation; specialist models choose searches, fetches, demo edits/tests and visual construction steps. - Decision owner: Shipped real Agent and runSubagent loops invoked through first-party models and tools; mere persistence/UI are not S1 decision owners. - Supporting / enforcement mechanisms: Per-turn persisted reconstruction, probe-to-teach seam, schema-validated question/plan tools, model selection and BYOK gates, structured worker toolsets, source-specific job persistence and abort handling. - Closure path: Learner goal/response → prober or teacher model decides action → asks/teaches/checks, or dispatches a specialist model → learner answers or worker returns evidence/artifact → teacher uses new information in following action. - Boundary reachability: handleChatRequest constructs buildAgent for the prober/teacher and jobTools dispatches to real shipped subagent runners; explicit configured model keys are needed. Scripted test engines do not supply the credited autonomy. - Why this is / is not agent-owned: Model agents select semantically different learning questions, explanation paths, search/fix iterations and specialist output; fixed question grading and JSON work queues alone cannot choose these. - Evidence: teacher runtime, job tool dispatch, researcher with web tools, demo builder with real headless check. - Basis: Shipped, model-backed adaptive operation and separately executable agent specialties. - Confidence: High source-path, medium live-provider efficacy (not executed). - Caveats: BYOK and required tool capabilities are deployment prerequisites. Tests use fake engines and do not validate pedagogical outcomes with real users.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: Would attenuate a conflict/oscillation specifically between independent lesson S1 workers and feed a revised coordination commitment into those workers. - Disturbance / variety regulated: Competing background job completions, shared graph writes, multiple specialist reports or two S1 units reaching incompatible conclusions. - Decisive decision or feedback right: Per-chat wake/steer deduplication and global graph audit lock serialize events; the teacher commissions specialists and receives their reports. No first-party autonomous inter-specialist disagreement negotiation or adjusted joint commitments is shown. - Decision owner: Deterministic job registry and semaphore control the mechanics; teacher handles the educational consequence as its S3/current-lesson decision, not a distinct inter-S1 S2 arbitration. - Supporting / enforcement mechanisms: Per-chat serialized wake delivery and recovery, durable pending result IDs, global limited concurrency, source-local extraction single-flight and global serialized audit/merge. - Closure path: Queued worker completion is delivered to teacher once; two graph audits cannot concurrently read and write a stale graph. This is mechanical admission/stability without a distinctive semantic response returned to the conflicting S1 workers. - Boundary reachability: The named locks, duplicate IDs, consent gates and worker result steers are live first-party source paths, but no separate model mediator resolves S1-vs-S1 work collision. - Why this is / is not agent-owned: Correct sequencing protects state, yet methodology requires specific inter-S1 disturbance, distinct discretionary response and returned adjustment of S1 behaviour, not delegation or a queue alone. - Evidence: serialized delivery / wake protocol, graph audit gate and source single-flight, six-system topology. - Basis: Bounded negative for agent-owned inter-S1 conflict attenuation; credible structural serialization is not enough. - Confidence: Medium-high. - Caveats: A user can ask the teacher to reconcile contradictory reports; no dedicated shipped inter-S1 coordination mandate is thereby established.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: Keep one current learning session coherent across the learner&#39;s goal, assessed understanding, dependency plan, teaching steps and commissioned specialist work. - Disturbance / variety regulated: Learner confusion invalidating current plan assumptions, wrong facts, delayed external support, mismatch between learning target and work in progress, specialist failures and changed user constraints. - Decisive decision or feedback right: The teacher has the current session transcript and goal, authors/revises the visible plan, decides which knowledge gap matters now, allocates research/demo/visual/PDF work and changes explanation/check sequence based on returned worker results and learner answers. - Decision owner: Model-bearing first-party teacher for the session-local teaching mission; learner can change the overall request, but deterministic planinit/queue enforcement is not the author of a new plan or delegation decision. - Supporting / enforcement mechanisms: Prober handoff, current session record, DAG validator, question node tags, job input and result steers, durable wake, one-turn active registry, disabled-tool and model-role settings. - Closure path: Prober establishes starting point → teacher builds global lesson dependency tree → learner&#39;s answers or independent job results reveal a current gap → teacher revises explanation/plan and initiates/cancels/uses supporting work → next quiz/lesson state reflects that decision. - Boundary reachability: buildAgent(&quot;teacher&quot;) is attached after the real probedone handoff, has plan and job tool access in the supported chat pipeline; background worker result messages return to this same persistent session. - Why this is / is not agent-owned: It is more than a blind router: the teacher decides a session-wide pedagogical priority and changes ongoing commitment to the goal in response to actual feedback. It does not manage the entire multi-session application, unrelated practice sets or a global provider budget. - Whole-system current view: Session transcript, learner goal, active plan/progress, commissioned worker result steers, and optional read-only graph inspection relevant to the session. - Current-control decision scope: Revise dependency plan/teaching sequence, task requests to multiple agents and response to produced evidence within the declared one-session recursion. - Evidence: teacher planning and on-the-fly repair, tool registry and model loop, worker feedback into live teacher, job instruction and correction. - Basis: Source-closed current session-wide semantic decision/return using autonomous teacher. Not a claim of product-wide S3 at higher recursion. - Confidence: Medium; stronger for declared one-session recursion than a broader multi-session organization. - Caveats: Plan progress tags are deterministic, not a second autonomous controller. No source proof of reliable cognitive diagnosis is inferred.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Reconcile the identity/novelty claim of graph propositions extracted from the session against separately read existing graph evidence before committing the update. - Disturbance / variety regulated: Duplicate concepts minted by distinct extraction runs or different sessions, same fact paraphrased as different graph nodes, or identity links based on stale graph snapshots. - Decisive decision or feedback right: A distinct model auditor explores the existing graph through find/listsessions/listpropositions and submits links; mergeFindings uses those judgments under the audit lock. It cannot inspect or fact-check the raw teaching source. - Decision owner: Separate first-party auditor agent makes semantic identity judgments, with deterministic serialization and merge applying them. No independent raw-source verification or challenge to extractor factual truth is present, so classify a narrow complementary constructor C, not general-purpose closed independent S3 A. - Supporting / enforcement mechanisms: Schema-bounded auditor submit, graph exploration tools, process-wide FIFO audit/merge lock, deterministic ledger writes, coverage checkpoints, rollback-on-stage-failure and source provenance. - Closure path: Extractor proposes lesson propositions → isolated auditor sees proposed propositions plus independently queried existing graph → returns identity links → merger collapses duplicate concepts or adds new ones → teacher can subsequently query the updated graph; no verified correction of teaching claims is claimed. - Boundary reachability: Enabled graph extraction invokes runAuditor in the standard source-to-ledger pipeline and mergeFindings consumes its output; BYOK extractor/auditor keys are required. It is a mandatory same-path graph integrity check, not a standing out-of-band lesson review. - Why this is / is not agent-owned: The auditor selects identity links through model exploration rather than code-only deduplication, but its complementary scope is narrow and the raw-source evidence boundary excludes stronger autonomous verification claims. - Claim being audited: Extractor&#39;s implicit assertion that newly proposed graph propositions are unique rather than semantic duplicates of an existing concept. - Ordinary reporting path: Extractor&#39;s submitted proposition list and source-local digest, subsequently represented as new graph nodes. - Complementary access path: Separate graph-aware model agent gets the live existing graph through first-party find/list tools while the extractor is isolated from that graph&#39;s full cross-source state. - Independence boundary: Distinct agent role, prompt and tools; no access to original source text, same application and possible underlying provider model; must not be confused with epistemic truth-checking. - Who acts on findings: The deterministic merger applies links immediately; the resulting graph is read-only exposed to future teacher sessions and the learner. - Evidence: auditor mandate and source exclusion, independent graph exploration tools, graph merge/evidence ledger. - Basis: Active model-backed narrow identity-audit constructor with complementary graph access; no independently validated correctness of the input claims. - Confidence: Medium for S3 constructor, high for its explicit limitations. - Caveats: Headless demo-browser tests occur inside the producing S1 worker and are not independent S3. A routine verifier in the same ingest path should not be promoted to a comprehensive audit of the lesson; future independent same-ref review could reasonably bound this to — if graph identity verification is considered inseparable production validation.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: Would scout changing external/future learning or agent capabilities and return options that alter the lesson organization&#39;s capability rather than just answer a current fact question. - Disturbance / variety regulated: Future model/tool shifts, curriculum/environment changes and novel teaching methods outside the present learner request. - Decisive decision or feedback right: Researcher retrieves outside evidence only for teacher&#39;s current informational need; learner/operator selects provider, prompt override and enabled tools by settings. No standing future-oriented strategy process is shown. - Decision owner: Teacher for current accuracy and human for manually changed app settings, not a distinct autonomous S4 opportunity/threat agent. - Supporting / enforcement mechanisms: Search/fetch researcher, durable cross-session knowledge graph, provider roles, prompt/settings UI and saved learner records. - Closure path: External research returns a cited brief into the current lesson and can correct facts, while persistent graph can inform later sessions; neither source path generates and adopts a prospective capability-change strategy. - Boundary reachability: Actual researcher and settings/graph surfaces exist; no future-option-to-S3 contract is established. - Why this is / is not agent-owned: Fetching recent facts and cumulative memory do not themselves create an outside-and-then intelligence function. - Evidence: researcher prompt and web tools, teacher research requirement, global model settings. - Basis: Bounded negative: external information serves the current session instead of strategic adaptation. - Confidence: High for reviewed standard path. - Caveats: A user may ask about future trends as a lesson topic; the topic alone does not make its executor S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: Would resolve an ultimate identity/purpose legitimacy conflict for the learning organization with binding authority and return a governing policy. - Disturbance / variety regulated: Conflicting fundamental educational goals or competing legitimacy claims rather than everyday disagreement about the next lesson step. - Decisive decision or feedback right: Learner chooses or changes the study goal and app configuration; teacher&#39;s instructions prescribe a method and ask the learner to approve the plan. No standing binding constitutional-purpose adjudication is wired. - Decision owner: Human learner sets the mission external to the autonomous lesson, teacher regulates subordinate pedagogical commitments. - Supporting / enforcement mechanisms: Probe/goal question, approval before teaching, role prompts, per-user provider and prompt settings. - Closure path: Learner can change the study target, and the next session turn adapts. This is ordinary task definition and plan review, not an adjudicated fundamental identity-policy dispute. - Boundary reachability: Goal elicitation and plan confirmation are active, but identity-level disagreement resolution and binding organizational policy are not established. - Why this is / is not agent-owned: A mandatory teaching philosophy in a system prompt is static implementation policy, not runtime S5 authority. - Evidence: probe/teach split, teacher&#39;s plan confirmation, fixed teaching identity. - Basis: Bounded negative for first-party policy legitimacy closure. - Confidence: High. - Caveats: A learner remains the legitimate authority to select its task, but task selection does not on its own justify S5=P at the present recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/e0377deccfa4315a6ad15781c29c8fa36bea6903/assessments/le/learnharness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit e0377deccfa4315a6ad15781c29c8fa36bea6903\">e0377de &#8599;</a></td></tr>"];
